window.CODIGO_JAVA["clientes-ms"] = {"src/main/java/com/mx/josesaid/develop/clientes/ClientesApplication.java": "package com.mx.josesaid.develop.clientes;\n\nimport org.springframework.boot.SpringApplication;\nimport org.springframework.boot.autoconfigure.SpringBootApplication;\nimport org.springframework.scheduling.annotation.EnableScheduling;\n\n/** Punto de entrada de clientes-ms: alta, seguimiento y consentimientos de clientes y prospectos. */\n@SpringBootApplication\n@EnableScheduling\npublic class ClientesApplication {\n\n    /** Arranca la aplicación Spring Boot. */\n    public static void main(String[] args) {\n        SpringApplication.run(ClientesApplication.class, args);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/api/Actor.java": "package com.mx.josesaid.develop.clientes.api;\n\nimport java.util.UUID;\nimport org.springframework.security.oauth2.jwt.Jwt;\n\n/** Identificador del usuario autenticado, tomado del claim sub, que debe ser un UUID. */\nfinal class Actor {\n\n    /** Clase de utilidad; no se instancia. */\n    private Actor() {\n    }\n\n    /** Obtiene el id del usuario autenticado desde el claim sub del JWT, que debe ser un UUID. */\n    static UUID de(Jwt jwt) {\n        return UUID.fromString(jwt.getSubject());\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/api/ApiDtos.java": "package com.mx.josesaid.develop.clientes.api;\n\nimport com.mx.josesaid.develop.clientes.domain.Cliente;\nimport com.mx.josesaid.develop.clientes.domain.Consentimiento;\nimport com.mx.josesaid.develop.clientes.domain.Contacto;\nimport com.mx.josesaid.develop.clientes.domain.EstatusCliente;\nimport com.mx.josesaid.develop.clientes.domain.EstatusProspecto;\nimport com.mx.josesaid.develop.clientes.domain.Fuente;\nimport com.mx.josesaid.develop.clientes.domain.Interaccion;\nimport com.mx.josesaid.develop.clientes.domain.MedioConsentimiento;\nimport com.mx.josesaid.develop.clientes.domain.Prospecto;\nimport com.mx.josesaid.develop.clientes.domain.RolContacto;\nimport com.mx.josesaid.develop.clientes.domain.TipoInteraccion;\nimport jakarta.validation.Valid;\nimport jakarta.validation.constraints.Email;\nimport jakarta.validation.constraints.NotBlank;\nimport jakarta.validation.constraints.NotNull;\nimport jakarta.validation.constraints.Pattern;\nimport jakarta.validation.constraints.Size;\nimport java.time.Instant;\nimport java.time.LocalDate;\nimport java.time.OffsetDateTime;\nimport java.util.UUID;\n\n/** DTOs de la API. Las respuestas enmascaran RFC, correo y nombre. */\npublic final class ApiDtos {\n\n    /** Formato del RFC de persona moral (3 letras) o física (4 letras), fecha AAMMDD y homoclave. */\n    public static final String PATRON_RFC = \"[A-Z&Ñ]{3,4}[0-9]{6}[A-Z0-9]{3}\";\n\n    /** Contenedor de los DTOs de la API. No se instancia. */\n    private ApiDtos() {\n    }\n\n    // ----- Peticiones -----\n\n    /**\n     * Datos para registrar un prospecto: nombre, correo, RFC, fuente y confirmación de duplicado si ya fue revisado.\n     *\n     * @param nombre nombre descriptivo, de tipo {@code String}.\n     * @param correo correo electrónico de contacto, de tipo {@code String}.\n     * @param rfc RFC fiscal de la persona o empresa, de tipo {@code String}.\n     * @param fuente fuente, de tipo {@code Fuente}.\n     */\n    public record NuevoProspectoRequest(\n            @NotBlank @Size(max = 200) String nombre,\n            @NotBlank @Email @Size(max = 254) String correo,\n            @Pattern(regexp = PATRON_RFC) String rfc,\n            @NotNull Fuente fuente) {\n    }\n\n    /**\n     * Cambio de estatus de un prospecto.\n     *\n     * @param estatus estado actual del registro, de tipo {@code EstatusProspecto}.\n     */\n    public record CambioEstatusProspectoRequest(@NotNull EstatusProspecto estatus) {\n    }\n\n    /**\n     * Cambio de estatus de un cliente.\n     *\n     * @param estatus estado actual del registro, de tipo {@code EstatusCliente}.\n     */\n    public record CambioEstatusClienteRequest(@NotNull EstatusCliente estatus) {\n    }\n\n    /**\n     * Datos de un contacto: nombre, correo y rol.\n     *\n     * @param nombre nombre descriptivo, de tipo {@code String}.\n     * @param correo correo electrónico de contacto, de tipo {@code String}.\n     * @param rol rol asignado, de tipo {@code RolContacto}.\n     */\n    public record DatosContactoRequest(\n            @NotBlank @Size(max = 200) String nombre,\n            @NotBlank @Email @Size(max = 254) String correo,\n            @NotNull RolContacto rol) {\n    }\n\n    /**\n     * Datos para convertir un prospecto en cliente: razón social, RFC y contacto principal.\n     *\n     * @param razonSocial razón social, de tipo {@code String}.\n     * @param rfc RFC fiscal de la persona o empresa, de tipo {@code String}.\n     * @param contactoPrincipal contacto principal, de tipo {@code DatosContactoRequest}.\n     */\n    public record ConvertirProspectoRequest(\n            @NotBlank @Size(max = 250) String razonSocial,\n            @NotBlank @Pattern(regexp = PATRON_RFC) String rfc,\n            @NotNull @Valid DatosContactoRequest contactoPrincipal) {\n    }\n\n    /**\n     * Datos para dar de alta un cliente directo, con su contacto principal.\n     *\n     * @param razonSocial razón social, de tipo {@code String}.\n     * @param rfc RFC fiscal de la persona o empresa, de tipo {@code String}.\n     * @param contactoPrincipal contacto principal, de tipo {@code DatosContactoRequest}.\n     */\n    public record NuevoClienteRequest(\n            @NotBlank @Size(max = 250) String razonSocial,\n            @NotBlank @Pattern(regexp = PATRON_RFC) String rfc,\n            @NotNull @Valid DatosContactoRequest contactoPrincipal) {\n    }\n\n    /**\n     * Cambio de la razón social de un cliente.\n     *\n     * @param razonSocial razón social, de tipo {@code String}.\n     */\n    public record ActualizarClienteRequest(@NotBlank @Size(max = 250) String razonSocial) {\n    }\n\n    /**\n     * Datos para agregar un contacto a un cliente, con indicador de principal.\n     *\n     * @param nombre nombre descriptivo, de tipo {@code String}.\n     * @param correo correo electrónico de contacto, de tipo {@code String}.\n     * @param rol rol asignado, de tipo {@code RolContacto}.\n     * @param principal principal, de tipo {@code boolean}.\n     */\n    public record ContactoRequest(\n            @NotBlank @Size(max = 200) String nombre,\n            @NotBlank @Email @Size(max = 254) String correo,\n            @NotNull RolContacto rol,\n            boolean principal) {\n    }\n\n    /**\n     * Datos de una interacción comercial: tipo, fecha y resumen.\n     *\n     * @param tipo tipo o clasificación del registro, de tipo {@code TipoInteraccion}.\n     * @param fecha fecha del registro, de tipo {@code Instant}.\n     * @param resumen resumen breve, de tipo {@code String}.\n     */\n    public record NuevaInteraccionRequest(\n            @NotNull TipoInteraccion tipo,\n            @NotNull Instant fecha,\n            @NotBlank @Size(max = 2000) String resumen) {\n    }\n\n    /**\n     * Datos de un consentimiento: finalidad, fecha, medio y vigencia.\n     *\n     * @param finalidad finalidad, de tipo {@code String}.\n     * @param fechaOtorgado fecha otorgado, de tipo {@code Instant}.\n     * @param medio medio, de tipo {@code MedioConsentimiento}.\n     * @param vigencia vigencia del registro, de tipo {@code LocalDate}.\n     */\n    public record NuevoConsentimientoRequest(\n            @NotBlank @Size(max = 100) String finalidad,\n            @NotNull Instant fechaOtorgado,\n            @NotNull MedioConsentimiento medio,\n            LocalDate vigencia) {\n    }\n\n    // ----- Respuestas -----\n\n    /**\n     * Respuesta de un prospecto. El correo, el nombre y el RFC van enmascarados.\n     *\n     * @param id identificador único del registro, de tipo {@code UUID}.\n     * @param nombre nombre descriptivo, de tipo {@code String}.\n     * @param correo correo electrónico de contacto, de tipo {@code String}.\n     * @param rfc RFC fiscal de la persona o empresa, de tipo {@code String}.\n     * @param fuente fuente, de tipo {@code Fuente}.\n     * @param estatus estado actual del registro, de tipo {@code EstatusProspecto}.\n     * @param fechaRegistro fecha registro, de tipo {@code LocalDate}.\n     * @param fechaConversion fecha conversion, de tipo {@code OffsetDateTime}.\n     */\n    public record ProspectoResponse(\n            UUID id,\n            String nombre,\n            String correo,\n            String rfc,\n            Fuente fuente,\n            EstatusProspecto estatus,\n            LocalDate fechaRegistro,\n            OffsetDateTime fechaConversion) {\n\n        /** Convierte un prospecto en su respuesta, con fechas en la zona de presentación y datos enmascarados. */\n        public static ProspectoResponse de(Prospecto p, Presentacion presentacion) {\n            return new ProspectoResponse(p.getId(), Mascara.nombre(p.getNombre()), Mascara.correo(p.getCorreo()),\n                    Mascara.rfc(p.getRfc()), p.getFuente(), p.getEstatus(), p.getFechaRegistro(),\n                    presentacion.fecha(p.getFechaConversion()));\n        }\n    }\n\n    /**\n     * Respuesta de un cliente.\n     *\n     * @param id identificador único del registro, de tipo {@code UUID}.\n     * @param razonSocial razón social, de tipo {@code String}.\n     * @param rfc RFC fiscal de la persona o empresa, de tipo {@code String}.\n     * @param estatus estado actual del registro, de tipo {@code EstatusCliente}.\n     * @param prospectoId identificador del prospecto, de tipo {@code UUID}.\n     * @param fechaAlta fecha alta, de tipo {@code LocalDate}.\n     */\n    public record ClienteResponse(\n            UUID id,\n            String razonSocial,\n            String rfc,\n            EstatusCliente estatus,\n            UUID prospectoId,\n            LocalDate fechaAlta) {\n\n        /** Convierte un cliente en su respuesta. */\n        public static ClienteResponse de(Cliente c) {\n            return new ClienteResponse(c.getId(), c.getRazonSocial(), Mascara.rfc(c.getRfc()), c.getEstatus(),\n                    c.getProspectoId(), c.getFechaAlta());\n        }\n    }\n\n    /**\n     * Resumen de un cliente con su última interacción.\n     *\n     * @param cliente cliente, de tipo {@code ClienteResponse}.\n     * @param ultimaInteraccion ultima interaccion, de tipo {@code InteraccionResponse}.\n     */\n    public record ClienteResumenResponse(ClienteResponse cliente, InteraccionResponse ultimaInteraccion) {\n    }\n\n    /**\n     * Respuesta de un contacto. El correo va enmascarado.\n     *\n     * @param id identificador único del registro, de tipo {@code UUID}.\n     * @param clienteId identificador del cliente, de tipo {@code UUID}.\n     * @param nombre nombre descriptivo, de tipo {@code String}.\n     * @param correo correo electrónico de contacto, de tipo {@code String}.\n     * @param rol rol asignado, de tipo {@code RolContacto}.\n     * @param principal principal, de tipo {@code boolean}.\n     */\n    public record ContactoResponse(\n            UUID id,\n            UUID clienteId,\n            String nombre,\n            String correo,\n            RolContacto rol,\n            boolean principal) {\n\n        /** Convierte un contacto en su respuesta, con el correo enmascarado. */\n        public static ContactoResponse de(Contacto c) {\n            return new ContactoResponse(c.getId(), c.getClienteId(), Mascara.nombre(c.getNombre()),\n                    Mascara.correo(c.getCorreo()), c.getRol(), c.isPrincipal());\n        }\n    }\n\n    /**\n     * Respuesta de una interacción.\n     *\n     * @param id identificador único del registro, de tipo {@code UUID}.\n     * @param clienteId identificador del cliente, de tipo {@code UUID}.\n     * @param tipo tipo o clasificación del registro, de tipo {@code TipoInteraccion}.\n     * @param fecha fecha del registro, de tipo {@code OffsetDateTime}.\n     * @param responsableId identificador del responsable, de tipo {@code UUID}.\n     * @param resumen resumen breve, de tipo {@code String}.\n     */\n    public record InteraccionResponse(\n            UUID id,\n            UUID clienteId,\n            TipoInteraccion tipo,\n            OffsetDateTime fecha,\n            UUID responsableId,\n            String resumen) {\n\n        /** Convierte una interacción en su respuesta, con la fecha en la zona de presentación. */\n        public static InteraccionResponse de(Interaccion i, Presentacion presentacion) {\n            return new InteraccionResponse(i.getId(), i.getClienteId(), i.getTipo(),\n                    presentacion.fecha(i.getFecha()), i.getResponsableId(), i.getResumen());\n        }\n    }\n\n    /**\n     * Respuesta de un consentimiento.\n     *\n     * @param id identificador único del registro, de tipo {@code UUID}.\n     * @param contactoId identificador del contacto, de tipo {@code UUID}.\n     * @param finalidad finalidad, de tipo {@code String}.\n     * @param fechaOtorgado fecha otorgado, de tipo {@code OffsetDateTime}.\n     * @param medio medio, de tipo {@code MedioConsentimiento}.\n     * @param vigencia vigencia del registro, de tipo {@code LocalDate}.\n     * @param revocadoEn revocado en, de tipo {@code OffsetDateTime}.\n     */\n    public record ConsentimientoResponse(\n            UUID id,\n            UUID contactoId,\n            String finalidad,\n            OffsetDateTime fechaOtorgado,\n            MedioConsentimiento medio,\n            LocalDate vigencia,\n            OffsetDateTime revocadoEn) {\n\n        /** Convierte un consentimiento en su respuesta, con fechas en la zona de presentación. */\n        public static ConsentimientoResponse de(Consentimiento c, Presentacion presentacion) {\n            return new ConsentimientoResponse(c.getId(), c.getContactoId(), c.getFinalidad(),\n                    presentacion.fecha(c.getFechaOtorgado()), c.getMedio(), c.getVigencia(),\n                    presentacion.fecha(c.getRevocadoAt()));\n        }\n    }\n\n    /**\n     * Conversiones de prospectos a clientes por mes.\n     *\n     * @param mes mes, de tipo {@code String}.\n     * @param conversiones conversiones, de tipo {@code long}.\n     */\n    public record MetricaConversionResponse(String mes, long conversiones) {\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/api/ClienteController.java": "package com.mx.josesaid.develop.clientes.api;\n\nimport com.mx.josesaid.develop.clientes.api.ApiDtos.ActualizarClienteRequest;\nimport com.mx.josesaid.develop.clientes.api.ApiDtos.CambioEstatusClienteRequest;\nimport com.mx.josesaid.develop.clientes.api.ApiDtos.ClienteResponse;\nimport com.mx.josesaid.develop.clientes.api.ApiDtos.ClienteResumenResponse;\nimport com.mx.josesaid.develop.clientes.api.ApiDtos.ContactoRequest;\nimport com.mx.josesaid.develop.clientes.api.ApiDtos.ContactoResponse;\nimport com.mx.josesaid.develop.clientes.api.ApiDtos.InteraccionResponse;\nimport com.mx.josesaid.develop.clientes.api.ApiDtos.NuevoClienteRequest;\nimport com.mx.josesaid.develop.clientes.application.Auditoria;\nimport com.mx.josesaid.develop.clientes.application.ClienteService;\nimport com.mx.josesaid.develop.clientes.application.Comandos;\nimport com.mx.josesaid.develop.clientes.domain.Cliente;\nimport com.mx.josesaid.develop.clientes.domain.Contacto;\nimport jakarta.validation.Valid;\nimport jakarta.validation.constraints.Size;\nimport java.net.URI;\nimport java.util.UUID;\nimport org.springframework.data.domain.Page;\nimport org.springframework.data.domain.Pageable;\nimport org.springframework.data.domain.Sort;\nimport org.springframework.data.web.PageableDefault;\nimport org.springframework.data.web.PagedModel;\nimport org.springframework.http.ResponseEntity;\nimport org.springframework.security.access.prepost.PreAuthorize;\nimport org.springframework.security.core.annotation.AuthenticationPrincipal;\nimport org.springframework.security.oauth2.jwt.Jwt;\nimport org.springframework.validation.annotation.Validated;\nimport org.springframework.web.bind.annotation.GetMapping;\nimport org.springframework.web.bind.annotation.PatchMapping;\nimport org.springframework.web.bind.annotation.PathVariable;\nimport org.springframework.web.bind.annotation.PostMapping;\nimport org.springframework.web.bind.annotation.RequestBody;\nimport org.springframework.web.bind.annotation.RequestMapping;\nimport org.springframework.web.bind.annotation.RequestParam;\nimport org.springframework.web.bind.annotation.RestController;\n\n/** Endpoints de clientes: alta, búsqueda, detalle, cambios de razón social y estatus, y contactos. */\n@RestController\n@Validated\n@RequestMapping(\"/v1/clientes\")\npublic class ClienteController {\n\n    private final ClienteService servicio;\n    private final Auditoria auditoria;\n    private final Presentacion presentacion;\n\n    /** Recibe el servicio de clientes, la auditoría y la zona de presentación. */\n    public ClienteController(ClienteService servicio, Auditoria auditoria, Presentacion presentacion) {\n        this.servicio = servicio;\n        this.auditoria = auditoria;\n        this.presentacion = presentacion;\n    }\n\n    /** Da de alta un cliente directo con su contacto principal. Registra la acción en la auditoría. */\n    @PostMapping\n    @PreAuthorize(\"hasRole('ADMIN')\")\n    public ResponseEntity<ClienteResponse> crear(@Valid @RequestBody NuevoClienteRequest req,\n                                                 @RequestParam(defaultValue = \"false\") boolean confirmarDuplicado) {\n        var contacto = req.contactoPrincipal();\n        Cliente creado = servicio.crear(new Comandos.NuevoCliente(req.razonSocial(), req.rfc(),\n                new Comandos.DatosContacto(contacto.nombre(), contacto.correo(), contacto.rol()), confirmarDuplicado));\n        return ResponseEntity.created(URI.create(\"/v1/clientes/\" + creado.getId()))\n                .body(ClienteResponse.de(creado));\n    }\n\n    /** Busca clientes por RFC exacto o por nombre parcial. Requiere al menos uno de los dos. */\n    @GetMapping\n    @PreAuthorize(\"hasAnyRole('VENTAS', 'ADMIN')\")\n    public PagedModel<ClienteResumenResponse> buscar(\n            @RequestParam(required = false) @Size(max = 13) String rfc,\n            @RequestParam(required = false) @Size(max = 200) String nombre,\n            @PageableDefault(size = 20, sort = \"razonSocial\", direction = Sort.Direction.ASC) Pageable pageable,\n            @AuthenticationPrincipal Jwt jwt) {\n        Page<Cliente> pagina = servicio.buscar(rfc, nombre, pageable);\n        auditoria.registrar(\"busqueda_clientes\", null, Actor.de(jwt));\n        return new PagedModel<>(pagina.map(c -> new ClienteResumenResponse(\n                ClienteResponse.de(c),\n                servicio.ultimaInteraccion(c.getId())\n                        .map(i -> InteraccionResponse.de(i, presentacion))\n                        .orElse(null))));\n    }\n\n    /** Devuelve el detalle de un cliente. Registra en la auditoría quién lo consultó. */\n    @GetMapping(\"/{id}\")\n    @PreAuthorize(\"hasAnyRole('VENTAS', 'ADMIN')\")\n    public ClienteResponse obtener(@PathVariable UUID id, @AuthenticationPrincipal Jwt jwt) {\n        Cliente cliente = servicio.obtener(id);\n        auditoria.registrar(\"consulta_cliente\", id, Actor.de(jwt));\n        return ClienteResponse.de(cliente);\n    }\n\n    /** Cambia la razón social de un cliente. */\n    @PatchMapping(\"/{id}\")\n    @PreAuthorize(\"hasRole('ADMIN')\")\n    public ClienteResponse actualizar(@PathVariable UUID id, @Valid @RequestBody ActualizarClienteRequest req) {\n        return ClienteResponse.de(servicio.actualizarRazonSocial(id, req.razonSocial()));\n    }\n\n    /** Cambia el estatus de un cliente. Las transiciones no permitidas se rechazan. */\n    @PatchMapping(\"/{id}/estatus\")\n    @PreAuthorize(\"hasRole('ADMIN')\")\n    public ClienteResponse cambiarEstatus(@PathVariable UUID id, @Valid @RequestBody CambioEstatusClienteRequest req) {\n        return ClienteResponse.de(servicio.cambiarEstatus(id, req.estatus()));\n    }\n\n    /** Agrega un contacto al cliente. Si es principal, desmarca el anterior. */\n    @PostMapping(\"/{id}/contactos\")\n    @PreAuthorize(\"hasRole('ADMIN')\")\n    public ResponseEntity<ContactoResponse> agregarContacto(@PathVariable UUID id,\n                                                            @Valid @RequestBody ContactoRequest req) {\n        Contacto contacto = servicio.agregarContacto(id, new Comandos.NuevoContacto(\n                req.nombre(), req.correo(), req.rol(), req.principal()));\n        return ResponseEntity.status(201).body(ContactoResponse.de(contacto));\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/api/ConsentimientoController.java": "package com.mx.josesaid.develop.clientes.api;\n\nimport com.mx.josesaid.develop.clientes.api.ApiDtos.ConsentimientoResponse;\nimport com.mx.josesaid.develop.clientes.api.ApiDtos.NuevoConsentimientoRequest;\nimport com.mx.josesaid.develop.clientes.application.Comandos;\nimport com.mx.josesaid.develop.clientes.application.ConsentimientoService;\nimport com.mx.josesaid.develop.clientes.domain.Consentimiento;\nimport jakarta.validation.Valid;\nimport java.util.UUID;\nimport org.springframework.http.ResponseEntity;\nimport org.springframework.security.access.prepost.PreAuthorize;\nimport org.springframework.web.bind.annotation.PathVariable;\nimport org.springframework.web.bind.annotation.PostMapping;\nimport org.springframework.web.bind.annotation.RequestBody;\nimport org.springframework.web.bind.annotation.RestController;\n\n/** Endpoints de consentimientos de contactos. */\n@RestController\npublic class ConsentimientoController {\n\n    private final ConsentimientoService servicio;\n    private final Presentacion presentacion;\n\n    /** Recibe el servicio de consentimientos y la zona de presentación. */\n    public ConsentimientoController(ConsentimientoService servicio, Presentacion presentacion) {\n        this.servicio = servicio;\n        this.presentacion = presentacion;\n    }\n\n    /** Registra el consentimiento de un contacto para una finalidad. */\n    @PostMapping(\"/v1/contactos/{contactoId}/consentimientos\")\n    @PreAuthorize(\"hasAnyRole('LEGAL', 'ADMIN')\")\n    public ResponseEntity<ConsentimientoResponse> otorgar(@PathVariable UUID contactoId,\n                                                          @Valid @RequestBody NuevoConsentimientoRequest req) {\n        Consentimiento otorgado = servicio.otorgar(contactoId, new Comandos.NuevoConsentimiento(\n                req.finalidad(), req.fechaOtorgado(), req.medio(), req.vigencia()));\n        return ResponseEntity.status(201).body(ConsentimientoResponse.de(otorgado, presentacion));\n    }\n\n    /** Revoca un consentimiento. La revocación queda registrada; no se borra. */\n    @PostMapping(\"/v1/consentimientos/{id}/revocacion\")\n    @PreAuthorize(\"hasAnyRole('LEGAL', 'ADMIN')\")\n    public ConsentimientoResponse revocar(@PathVariable UUID id) {\n        return ConsentimientoResponse.de(servicio.revocar(id), presentacion);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/api/InteraccionController.java": "package com.mx.josesaid.develop.clientes.api;\n\nimport com.mx.josesaid.develop.clientes.api.ApiDtos.InteraccionResponse;\nimport com.mx.josesaid.develop.clientes.api.ApiDtos.NuevaInteraccionRequest;\nimport com.mx.josesaid.develop.clientes.application.Auditoria;\nimport com.mx.josesaid.develop.clientes.application.Comandos;\nimport com.mx.josesaid.develop.clientes.application.InteraccionService;\nimport com.mx.josesaid.develop.clientes.domain.Interaccion;\nimport jakarta.validation.Valid;\nimport java.net.URI;\nimport java.util.UUID;\nimport org.springframework.data.domain.Page;\nimport org.springframework.data.domain.Pageable;\nimport org.springframework.data.domain.Sort;\nimport org.springframework.data.web.PageableDefault;\nimport org.springframework.data.web.PagedModel;\nimport org.springframework.http.ResponseEntity;\nimport org.springframework.security.access.prepost.PreAuthorize;\nimport org.springframework.security.core.annotation.AuthenticationPrincipal;\nimport org.springframework.security.oauth2.jwt.Jwt;\nimport org.springframework.web.bind.annotation.GetMapping;\nimport org.springframework.web.bind.annotation.PathVariable;\nimport org.springframework.web.bind.annotation.PostMapping;\nimport org.springframework.web.bind.annotation.RequestBody;\nimport org.springframework.web.bind.annotation.RequestMapping;\nimport org.springframework.web.bind.annotation.RestController;\n\n/** Endpoints de interacciones comerciales de un cliente. */\n@RestController\n@RequestMapping(\"/v1/clientes/{clienteId}/interacciones\")\npublic class InteraccionController {\n\n    private final InteraccionService servicio;\n    private final Auditoria auditoria;\n    private final Presentacion presentacion;\n\n    /** Recibe el servicio de interacciones, la auditoría y la zona de presentación. */\n    public InteraccionController(InteraccionService servicio, Auditoria auditoria, Presentacion presentacion) {\n        this.servicio = servicio;\n        this.auditoria = auditoria;\n        this.presentacion = presentacion;\n    }\n\n    /** Registra una interacción con el cliente. El responsable es el usuario autenticado. */\n    @PostMapping\n    @PreAuthorize(\"hasAnyRole('VENTAS', 'ADMIN')\")\n    public ResponseEntity<InteraccionResponse> registrar(@PathVariable UUID clienteId,\n                                                         @Valid @RequestBody NuevaInteraccionRequest req,\n                                                         @AuthenticationPrincipal Jwt jwt) {\n        Interaccion creada = servicio.registrar(clienteId,\n                new Comandos.NuevaInteraccion(req.tipo(), req.fecha(), req.resumen()), Actor.de(jwt));\n        return ResponseEntity.created(URI.create(\"/v1/clientes/\" + clienteId + \"/interacciones/\" + creada.getId()))\n                .body(InteraccionResponse.de(creada, presentacion));\n    }\n\n    /** Lista las interacciones de un cliente, paginadas. */\n    @GetMapping\n    @PreAuthorize(\"hasAnyRole('VENTAS', 'ADMIN')\")\n    public PagedModel<InteraccionResponse> listar(\n            @PathVariable UUID clienteId,\n            @PageableDefault(size = 20, sort = \"fecha\", direction = Sort.Direction.DESC) Pageable pageable,\n            @AuthenticationPrincipal Jwt jwt) {\n        Page<Interaccion> pagina = servicio.listar(clienteId, pageable);\n        auditoria.registrar(\"consulta_interacciones\", clienteId, Actor.de(jwt));\n        return new PagedModel<>(pagina.map(i -> InteraccionResponse.de(i, presentacion)));\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/api/ManejadorErrores.java": "package com.mx.josesaid.develop.clientes.api;\n\nimport com.mx.josesaid.develop.clientes.application.ConflictoRfcException;\nimport com.mx.josesaid.develop.clientes.application.DuplicadoPosibleException;\nimport com.mx.josesaid.develop.clientes.application.EntidadNoEncontradaException;\nimport com.mx.josesaid.develop.clientes.application.ReglaNegocioException;\nimport com.mx.josesaid.develop.clientes.domain.TransicionInvalidaException;\nimport java.net.URI;\nimport java.util.List;\nimport java.util.Map;\nimport org.springframework.dao.DataIntegrityViolationException;\nimport org.springframework.http.HttpStatus;\nimport org.springframework.http.ProblemDetail;\nimport jakarta.validation.ConstraintViolationException;\nimport org.springframework.web.bind.MethodArgumentNotValidException;\nimport org.springframework.web.bind.annotation.ExceptionHandler;\nimport org.springframework.web.bind.annotation.RestControllerAdvice;\n\n/**\n * Convierte excepciones en respuestas RFC 9457 (application/problem+json).\n * Los tipos son URN estables: {@code urn:clientes:error:<codigo>}.\n */\n@RestControllerAdvice\npublic class ManejadorErrores {\n\n    /** Convierte un recurso inexistente en un problema HTTP. */\n    @ExceptionHandler(EntidadNoEncontradaException.class)\n    ProblemDetail noEncontrado(EntidadNoEncontradaException e) {\n        return problema(HttpStatus.NOT_FOUND, \"recurso-no-encontrado\", \"Recurso no encontrado\", e.getMessage());\n    }\n\n    /** Convierte un RFC ya registrado en un problema HTTP, con el id del cliente existente. */\n    @ExceptionHandler(ConflictoRfcException.class)\n    ProblemDetail rfcDuplicado(ConflictoRfcException e) {\n        ProblemDetail pd = problema(HttpStatus.CONFLICT, \"rfc-duplicado\", \"Conflicto de RFC\", e.getMessage());\n        pd.setProperty(\"clienteExistenteId\", e.getClienteExistenteId());\n        return pd;\n    }\n\n    /** Convierte un posible duplicado en un problema HTTP con las coincidencias encontradas. */\n    @ExceptionHandler(DuplicadoPosibleException.class)\n    ProblemDetail posibleDuplicado(DuplicadoPosibleException e) {\n        ProblemDetail pd = problema(HttpStatus.CONFLICT, \"posible-duplicado\", \"Posible duplicado\",\n                \"Confirme la alta con ?confirmarDuplicado=true\");\n        pd.setProperty(\"coincidencias\", e.getCoincidencias());\n        return pd;\n    }\n\n    /** Convierte una transición de estatus no permitida en un problema HTTP. */\n    @ExceptionHandler(TransicionInvalidaException.class)\n    ProblemDetail transicionInvalida(TransicionInvalidaException e) {\n        return problema(HttpStatus.CONFLICT, \"transicion-invalida\", \"Transición no permitida\", e.getMessage());\n    }\n\n    /** Convierte una regla de negocio incumplida en un problema HTTP. */\n    @ExceptionHandler(ReglaNegocioException.class)\n    ProblemDetail reglaDeNegocio(ReglaNegocioException e) {\n        return problema(HttpStatus.UNPROCESSABLE_ENTITY, \"regla-de-negocio\", \"Regla de negocio\", e.getMessage());\n    }\n\n    /** Convierte una violación de integridad de la base en un problema HTTP, sin revelar detalles internos. */\n    @ExceptionHandler(DataIntegrityViolationException.class)\n    ProblemDetail integridad(DataIntegrityViolationException e) {\n        return problema(HttpStatus.CONFLICT, \"conflicto-de-integridad\", \"Conflicto de integridad\",\n                \"La operación viola una restricción única; reintente consultando el registro existente\");\n    }\n\n    /** Convierte errores de validación de los datos recibidos en un problema HTTP con el detalle de cada campo. */\n    @ExceptionHandler(MethodArgumentNotValidException.class)\n    ProblemDetail validacion(MethodArgumentNotValidException e) {\n        List<Map<String, String>> errores = e.getBindingResult().getFieldErrors().stream()\n                .map(f -> Map.of(\"campo\", f.getField(), \"mensaje\", String.valueOf(f.getDefaultMessage())))\n                .toList();\n        ProblemDetail pd = problema(HttpStatus.BAD_REQUEST, \"validacion\", \"Datos inválidos\",\n                \"Revise los campos indicados\");\n        pd.setProperty(\"errores\", errores);\n        return pd;\n    }\n\n    /** Convierte parámetros inválidos en un problema HTTP. */\n    @ExceptionHandler(ConstraintViolationException.class)\n    ProblemDetail parametrosInvalidos(ConstraintViolationException e) {\n        List<Map<String, String>> errores = e.getConstraintViolations().stream()\n                .map(v -> Map.of(\"campo\", String.valueOf(v.getPropertyPath()), \"mensaje\", String.valueOf(v.getMessage())))\n                .toList();\n        ProblemDetail pd = problema(HttpStatus.BAD_REQUEST, \"validacion\", \"Parámetros inválidos\",\n                \"Revise los parámetros indicados\");\n        pd.setProperty(\"errores\", errores);\n        return pd;\n    }\n\n    /** Construye la respuesta de error con su código, título y detalle. */\n    private static ProblemDetail problema(HttpStatus estado, String codigo, String titulo, String detalle) {\n        ProblemDetail pd = ProblemDetail.forStatusAndDetail(estado, detalle);\n        pd.setType(URI.create(\"urn:clientes:error:\" + codigo));\n        pd.setTitle(titulo);\n        return pd;\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/api/Mascara.java": "package com.mx.josesaid.develop.clientes.api;\n\n/** Enmascarado de datos personales para respuestas. Los logs nunca usan estos valores. */\npublic final class Mascara {\n\n    /** Clase de utilidad; no se instancia. */\n    private Mascara() {\n    }\n\n    /** Muestra las tres primeras y las dos últimas posiciones. Ej.: IDE*******Y1 */\n    public static String rfc(String rfc) {\n        if (rfc == null) {\n            return null;\n        }\n        int longitud = rfc.length();\n        if (longitud <= 5) {\n            return \"*\".repeat(longitud);\n        }\n        return rfc.substring(0, 3) + \"*\".repeat(longitud - 5) + rfc.substring(longitud - 2);\n    }\n\n    /** Muestra la primera letra y el dominio. Ej.: a***@ejemplo.mx */\n    public static String correo(String correo) {\n        if (correo == null) {\n            return null;\n        }\n        int arroba = correo.indexOf('@');\n        if (arroba <= 0) {\n            return \"***\";\n        }\n        return correo.substring(0, 1) + \"***\" + correo.substring(arroba);\n    }\n\n    /** Muestra solo la primera letra. Ej.: A*** */\n    public static String nombre(String nombre) {\n        if (nombre == null) {\n            return null;\n        }\n        String recortado = nombre.trim();\n        if (recortado.isEmpty()) {\n            return \"\";\n        }\n        return recortado.substring(0, 1) + \"***\";\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/api/MetricasController.java": "package com.mx.josesaid.develop.clientes.api;\n\nimport com.mx.josesaid.develop.clientes.api.ApiDtos.MetricaConversionResponse;\nimport com.mx.josesaid.develop.clientes.application.MetricasService;\nimport java.time.YearMonth;\nimport org.springframework.format.annotation.DateTimeFormat;\nimport org.springframework.security.access.prepost.PreAuthorize;\nimport org.springframework.web.bind.annotation.GetMapping;\nimport org.springframework.web.bind.annotation.RequestMapping;\nimport org.springframework.web.bind.annotation.RequestParam;\nimport org.springframework.web.bind.annotation.RestController;\n\n/** Endpoints de métricas comerciales. */\n@RestController\n@RequestMapping(\"/v1/metricas\")\npublic class MetricasController {\n\n    private final MetricasService servicio;\n\n    /** Recibe el servicio de métricas. */\n    public MetricasController(MetricasService servicio) {\n        this.servicio = servicio;\n    }\n\n    /** Devuelve cuántos prospectos se convirtieron en clientes en el mes indicado. */\n    @GetMapping(\"/conversion\")\n    @PreAuthorize(\"hasAnyRole('VENTAS', 'ADMIN')\")\n    public MetricaConversionResponse conversion(\n            @RequestParam @DateTimeFormat(pattern = \"yyyy-MM\") YearMonth mes) {\n        return new MetricaConversionResponse(mes.toString(), servicio.conversionesDelMes(mes));\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/api/Presentacion.java": "package com.mx.josesaid.develop.clientes.api;\n\nimport java.time.Instant;\nimport java.time.OffsetDateTime;\nimport java.time.ZoneId;\nimport org.springframework.beans.factory.annotation.Value;\nimport org.springframework.stereotype.Component;\n\n/** Convierte instantes UTC a la zona de presentación. Es la única capa que hace esta conversión. */\n@Component\npublic class Presentacion {\n\n    private final ZoneId zona;\n\n    /** Recibe la zona horaria con la que se muestran las fechas al cliente de la API. */\n    public Presentacion(@Value(\"${app.zona-presentacion}\") String zona) {\n        this.zona = ZoneId.of(zona);\n    }\n\n    /** Convierte un instante UTC a fecha y hora en la zona de presentación. */\n    public OffsetDateTime fecha(Instant instante) {\n        return instante == null ? null : instante.atZone(zona).toOffsetDateTime();\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/api/ProspectoController.java": "package com.mx.josesaid.develop.clientes.api;\n\nimport com.mx.josesaid.develop.clientes.api.ApiDtos.CambioEstatusProspectoRequest;\nimport com.mx.josesaid.develop.clientes.api.ApiDtos.ClienteResponse;\nimport com.mx.josesaid.develop.clientes.api.ApiDtos.ConvertirProspectoRequest;\nimport com.mx.josesaid.develop.clientes.api.ApiDtos.NuevoProspectoRequest;\nimport com.mx.josesaid.develop.clientes.api.ApiDtos.ProspectoResponse;\nimport com.mx.josesaid.develop.clientes.application.Auditoria;\nimport com.mx.josesaid.develop.clientes.application.Comandos;\nimport com.mx.josesaid.develop.clientes.application.ProspectoService;\nimport com.mx.josesaid.develop.clientes.domain.Prospecto;\nimport jakarta.validation.Valid;\nimport java.net.URI;\nimport org.springframework.http.ResponseEntity;\nimport org.springframework.security.core.annotation.AuthenticationPrincipal;\nimport org.springframework.security.oauth2.jwt.Jwt;\nimport org.springframework.security.access.prepost.PreAuthorize;\nimport org.springframework.web.bind.annotation.GetMapping;\nimport org.springframework.web.bind.annotation.PatchMapping;\nimport org.springframework.web.bind.annotation.PathVariable;\nimport org.springframework.web.bind.annotation.PostMapping;\nimport org.springframework.web.bind.annotation.RequestBody;\nimport org.springframework.web.bind.annotation.RequestMapping;\nimport org.springframework.web.bind.annotation.RequestParam;\nimport org.springframework.web.bind.annotation.RestController;\nimport java.util.UUID;\n\n/** Endpoints de prospectos: alta, detalle, cambio de estatus y conversión a cliente. */\n@RestController\n@RequestMapping(\"/v1/prospectos\")\npublic class ProspectoController {\n\n    private final ProspectoService servicio;\n    private final Auditoria auditoria;\n    private final Presentacion presentacion;\n\n    /** Recibe el servicio de prospectos, la auditoría y la zona de presentación. */\n    public ProspectoController(ProspectoService servicio, Auditoria auditoria, Presentacion presentacion) {\n        this.servicio = servicio;\n        this.auditoria = auditoria;\n        this.presentacion = presentacion;\n    }\n\n    /** Registra un prospecto. Si hay posibles duplicados, responde con las coincidencias para que el usuario confirme. */\n    @PostMapping\n    @PreAuthorize(\"hasAnyRole('VENTAS', 'ADMIN')\")\n    public ResponseEntity<ProspectoResponse> crear(@Valid @RequestBody NuevoProspectoRequest req,\n                                                   @RequestParam(defaultValue = \"false\") boolean confirmarDuplicado) {\n        Prospecto creado = servicio.crear(new Comandos.NuevoProspecto(\n                req.nombre(), req.correo(), req.rfc(), req.fuente(), confirmarDuplicado));\n        return ResponseEntity.created(URI.create(\"/v1/prospectos/\" + creado.getId()))\n                .body(ProspectoResponse.de(creado, presentacion));\n    }\n\n    /** Devuelve el detalle de un prospecto. Registra en la auditoría quién lo consultó. */\n    @GetMapping(\"/{id}\")\n    @PreAuthorize(\"hasAnyRole('VENTAS', 'ADMIN')\")\n    public ProspectoResponse obtener(@PathVariable UUID id, @AuthenticationPrincipal Jwt jwt) {\n        Prospecto prospecto = servicio.obtener(id);\n        auditoria.registrar(\"consulta_prospecto\", id, Actor.de(jwt));\n        return ProspectoResponse.de(prospecto, presentacion);\n    }\n\n    /** Cambia el estatus de un prospecto. */\n    @PatchMapping(\"/{id}/estatus\")\n    @PreAuthorize(\"hasAnyRole('VENTAS', 'ADMIN')\")\n    public ProspectoResponse cambiarEstatus(@PathVariable UUID id,\n                                            @Valid @RequestBody CambioEstatusProspectoRequest req) {\n        return ProspectoResponse.de(servicio.cambiarEstatus(id, req.estatus()), presentacion);\n    }\n\n    /** Convierte un prospecto calificado en cliente con su contacto principal. */\n    @PostMapping(\"/{id}/conversion\")\n    @PreAuthorize(\"hasAnyRole('VENTAS', 'ADMIN')\")\n    public ResponseEntity<ClienteResponse> convertir(@PathVariable UUID id,\n                                                     @Valid @RequestBody ConvertirProspectoRequest req) {\n        var contacto = req.contactoPrincipal();\n        var cliente = servicio.convertir(id, new Comandos.ConvertirProspecto(req.razonSocial(), req.rfc(),\n                new Comandos.DatosContacto(contacto.nombre(), contacto.correo(), contacto.rol())));\n        return ResponseEntity.created(URI.create(\"/v1/clientes/\" + cliente.getId()))\n                .body(ClienteResponse.de(cliente));\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/application/Auditoria.java": "package com.mx.josesaid.develop.clientes.application;\n\nimport java.util.UUID;\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\nimport org.springframework.stereotype.Component;\n\n/**\n * Registro de accesos a datos personales. Solo registra operación, identificador del recurso y\n * sub del actor. Nunca registra el contenido de los datos.\n */\n@Component\npublic class Auditoria {\n\n    private static final Logger LOG = LoggerFactory.getLogger(\"auditoria.datos_personales\");\n\n    /** Registra en el log quién hizo una operación sobre un recurso. Solo guarda ids, nunca datos personales. */\n    public void registrar(String operacion, UUID recurso, UUID actor) {\n        LOG.info(\"operacion={} recurso={} actor={}\", operacion, recurso, actor);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/application/ClienteService.java": "package com.mx.josesaid.develop.clientes.application;\n\nimport com.mx.josesaid.develop.clientes.domain.FechasNegocio;\nimport com.mx.josesaid.develop.clientes.application.Comandos.NuevoCliente;\nimport com.mx.josesaid.develop.clientes.application.Comandos.NuevoContacto;\nimport com.mx.josesaid.develop.clientes.domain.Cliente;\nimport com.mx.josesaid.develop.clientes.domain.Contacto;\nimport com.mx.josesaid.develop.clientes.domain.EstatusCliente;\nimport com.mx.josesaid.develop.clientes.domain.Interaccion;\nimport com.mx.josesaid.develop.clientes.infrastructure.crypto.IndiceHash;\nimport com.mx.josesaid.develop.clientes.infrastructure.persistence.ClienteRepository;\nimport com.mx.josesaid.develop.clientes.infrastructure.persistence.ContactoRepository;\nimport com.mx.josesaid.develop.clientes.infrastructure.persistence.InteraccionRepository;\nimport io.micrometer.core.instrument.MeterRegistry;\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.util.Map;\nimport java.util.Optional;\nimport java.util.UUID;\nimport org.springframework.data.domain.Page;\nimport org.springframework.data.domain.Pageable;\nimport org.springframework.stereotype.Service;\nimport org.springframework.transaction.annotation.Transactional;\n\n/** Lógica de negocio de clientes: alta, búsqueda, cambios de estatus y contactos. */\n@Service\n@Transactional\npublic class ClienteService {\n\n    private final ClienteRepository clientes;\n    private final ContactoRepository contactos;\n    private final InteraccionRepository interacciones;\n    private final DetectorDuplicados duplicados;\n    private final RegistradorEventos eventos;\n    private final MeterRegistry metricas;\n    private final Clock reloj;\n\n    /** Recibe los repositorios, el detector de duplicados, el registrador de eventos, las métricas y el reloj. */\n    public ClienteService(ClienteRepository clientes, ContactoRepository contactos, InteraccionRepository interacciones,\n                          DetectorDuplicados duplicados, RegistradorEventos eventos,\n                          MeterRegistry metricas, Clock reloj) {\n        this.clientes = clientes;\n        this.contactos = contactos;\n        this.interacciones = interacciones;\n        this.duplicados = duplicados;\n        this.eventos = eventos;\n        this.metricas = metricas;\n        this.reloj = reloj;\n    }\n\n    /** Alta directa de cliente. Siempre crea un contacto principal. */\n    public Cliente crear(NuevoCliente cmd) {\n        String rfc = Normalizacion.rfc(cmd.rfc());\n        duplicados.validarRfcUnico(rfc);\n        duplicados.validarPosibles(cmd.contactoPrincipal().correo(), cmd.razonSocial(), cmd.confirmarDuplicado());\n\n        Instant ahora = Instant.now(reloj);\n        UUID clienteId = UUID.randomUUID();\n        UUID contactoId = UUID.randomUUID();\n        Cliente cliente = clientes.save(Cliente.nuevo(clienteId, cmd.razonSocial(), rfc, null, FechasNegocio.hoy(reloj), ahora));\n        contactos.save(Contacto.nuevo(contactoId, clienteId, cmd.contactoPrincipal().nombre(),\n                cmd.contactoPrincipal().correo(), cmd.contactoPrincipal().rol(), true, ahora));\n\n        eventos.registrar(\"cliente\", clienteId, \"ClienteCreado\", Map.of(\n                \"clienteId\", clienteId.toString(),\n                \"contactoPrincipalId\", contactoId.toString(),\n                \"estatus\", cliente.getEstatus().name()));\n        metricas.counter(\"clientes.altas\", \"tipo\", \"cliente\").increment();\n        return cliente;\n    }\n\n    /** Búsqueda por RFC (exacta) o por nombre (parcial, sin distinguir mayúsculas). Requiere al menos uno. */\n    @Transactional(readOnly = true)\n    public Page<Cliente> buscar(String rfc, String nombre, Pageable pageable) {\n        String rfcNormalizado = Normalizacion.rfc(rfc);\n        if (rfcNormalizado != null) {\n            return clientes.findByRfcHash(IndiceHash.rfc(rfcNormalizado), pageable);\n        }\n        if (nombre == null || nombre.isBlank()) {\n            throw new ReglaNegocioException(\"Indique al menos un criterio de búsqueda: rfc o nombre\");\n        }\n        return clientes.findByRazonSocialContainingIgnoreCase(nombre.trim(), pageable);\n    }\n\n    /** Devuelve un cliente por id o lanza EntidadNoEncontradaException. */\n    @Transactional(readOnly = true)\n    public Cliente obtener(UUID id) {\n        return clientes.findById(id).orElseThrow(() -> new EntidadNoEncontradaException(\"cliente\", id));\n    }\n\n    /** Devuelve la interacción más reciente de un cliente, si existe. */\n    @Transactional(readOnly = true)\n    public Optional<Interaccion> ultimaInteraccion(UUID clienteId) {\n        return interacciones.findFirstByClienteIdOrderByFechaDesc(clienteId);\n    }\n\n    /** Cambia la razón social de un cliente tras validar que no esté vacía. */\n    public Cliente actualizarRazonSocial(UUID id, String razonSocial) {\n        Cliente cliente = obtener(id);\n        cliente.actualizarRazonSocial(razonSocial, Instant.now(reloj));\n        return cliente;\n    }\n\n    /** Cambia el estatus. Idempotente. Emite ClienteEstatusCambiado solo si el estatus cambia. */\n    public Cliente cambiarEstatus(UUID id, EstatusCliente destino) {\n        Cliente cliente = obtener(id);\n        EstatusCliente anterior = cliente.getEstatus();\n        cliente.cambiarEstatus(destino, Instant.now(reloj));\n        if (anterior != destino) {\n            eventos.registrar(\"cliente\", id, \"ClienteEstatusCambiado\", Map.of(\n                    \"clienteId\", id.toString(),\n                    \"estatusAnterior\", anterior.name(),\n                    \"estatusNuevo\", destino.name()));\n        }\n        return cliente;\n    }\n\n    /** Agrega un contacto. Si es principal, el anterior principal se desmarca en la misma transacción. */\n    public Contacto agregarContacto(UUID clienteId, NuevoContacto cmd) {\n        obtener(clienteId);\n        Instant ahora = Instant.now(reloj);\n        if (cmd.principal()) {\n            contactos.findFirstByClienteIdAndPrincipalTrue(clienteId).ifPresent(anterior -> {\n                anterior.desmarcarPrincipal(ahora);\n                contactos.saveAndFlush(anterior);\n            });\n        }\n        return contactos.saveAndFlush(Contacto.nuevo(UUID.randomUUID(), clienteId, cmd.nombre(), cmd.correo(),\n                cmd.rol(), cmd.principal(), ahora));\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/application/Coincidencia.java": "package com.mx.josesaid.develop.clientes.application;\n\nimport java.util.UUID;\n\n/**\n * Posible duplicado encontrado: criterio (\"correo\", \"nombre\" o \"razon_social\"), tipo de registro e identificador.\n *\n * @param criterio criterio, de tipo {@code String}.\n * @param tipoRegistro tipo registro, de tipo {@code String}.\n * @param id identificador único del registro, de tipo {@code UUID}.\n */\npublic record Coincidencia(String criterio, String tipoRegistro, UUID id) {\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/application/Comandos.java": "package com.mx.josesaid.develop.clientes.application;\n\nimport com.mx.josesaid.develop.clientes.domain.Fuente;\nimport com.mx.josesaid.develop.clientes.domain.MedioConsentimiento;\nimport com.mx.josesaid.develop.clientes.domain.RolContacto;\nimport com.mx.josesaid.develop.clientes.domain.TipoInteraccion;\nimport java.time.Instant;\nimport java.time.LocalDate;\n\n/** Comandos de entrada de los casos de uso. La capa application no conoce DTOs HTTP. */\npublic final class Comandos {\n\n    /** Clase de utilidad con los comandos de la capa de aplicación; no se instancia. */\n    private Comandos() {\n    }\n\n    /**\n     * Datos de un contacto recibidos para registrar.\n     *\n     * @param nombre nombre descriptivo, de tipo {@code String}.\n     * @param correo correo electrónico de contacto, de tipo {@code String}.\n     * @param rol rol asignado, de tipo {@code RolContacto}.\n     */\n    public record DatosContacto(String nombre, String correo, RolContacto rol) {\n    }\n\n    /**\n     * Datos para registrar un prospecto. Si confirmarDuplicado es verdadero, se acepta una coincidencia parcial.\n     *\n     * @param nombre nombre descriptivo, de tipo {@code String}.\n     * @param correo correo electrónico de contacto, de tipo {@code String}.\n     * @param rfc RFC fiscal de la persona o empresa, de tipo {@code String}.\n     * @param fuente fuente, de tipo {@code Fuente}.\n     * @param confirmarDuplicado confirmar duplicado, de tipo {@code boolean}.\n     */\n    public record NuevoProspecto(String nombre, String correo, String rfc, Fuente fuente, boolean confirmarDuplicado) {\n    }\n\n    /**\n     * Datos para convertir un prospecto en cliente.\n     *\n     * @param razonSocial razón social, de tipo {@code String}.\n     * @param rfc RFC fiscal de la persona o empresa, de tipo {@code String}.\n     * @param contactoPrincipal contacto principal, de tipo {@code DatosContacto}.\n     */\n    public record ConvertirProspecto(String razonSocial, String rfc, DatosContacto contactoPrincipal) {\n    }\n\n    /**\n     * Datos para dar de alta un cliente directo.\n     *\n     * @param razonSocial razón social, de tipo {@code String}.\n     * @param rfc RFC fiscal de la persona o empresa, de tipo {@code String}.\n     * @param contactoPrincipal contacto principal, de tipo {@code DatosContacto}.\n     * @param confirmarDuplicado confirmar duplicado, de tipo {@code boolean}.\n     */\n    public record NuevoCliente(String razonSocial, String rfc, DatosContacto contactoPrincipal, boolean confirmarDuplicado) {\n    }\n\n    /**\n     * Datos de un contacto a agregar a un cliente.\n     *\n     * @param nombre nombre descriptivo, de tipo {@code String}.\n     * @param correo correo electrónico de contacto, de tipo {@code String}.\n     * @param rol rol asignado, de tipo {@code RolContacto}.\n     * @param principal principal, de tipo {@code boolean}.\n     */\n    public record NuevoContacto(String nombre, String correo, RolContacto rol, boolean principal) {\n    }\n\n    /**\n     * Datos de una interacción comercial.\n     *\n     * @param tipo tipo o clasificación del registro, de tipo {@code TipoInteraccion}.\n     * @param fecha fecha del registro, de tipo {@code Instant}.\n     * @param resumen resumen breve, de tipo {@code String}.\n     */\n    public record NuevaInteraccion(TipoInteraccion tipo, Instant fecha, String resumen) {\n    }\n\n    /**\n     * Datos de un consentimiento a registrar.\n     *\n     * @param finalidad finalidad, de tipo {@code String}.\n     * @param fechaOtorgado fecha otorgado, de tipo {@code Instant}.\n     * @param medio medio, de tipo {@code MedioConsentimiento}.\n     * @param vigencia vigencia del registro, de tipo {@code LocalDate}.\n     */\n    public record NuevoConsentimiento(String finalidad, Instant fechaOtorgado, MedioConsentimiento medio, LocalDate vigencia) {\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/application/ConflictoRfcException.java": "package com.mx.josesaid.develop.clientes.application;\n\nimport java.util.UUID;\n\n/** Ya existe un cliente no dado de baja con el mismo RFC. */\npublic class ConflictoRfcException extends RuntimeException {\n\n    private final UUID clienteExistenteId;\n\n    /** Se lanza cuando el RFC ya pertenece a un cliente activo. Guarda el id de ese cliente. */\n    public ConflictoRfcException(UUID clienteExistenteId) {\n        super(\"Ya existe un cliente activo con ese RFC\");\n        this.clienteExistenteId = clienteExistenteId;\n    }\n\n    /** Devuelve el id del cliente que ya tiene ese RFC. */\n    public UUID getClienteExistenteId() {\n        return clienteExistenteId;\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/application/ConsentimientoService.java": "package com.mx.josesaid.develop.clientes.application;\n\nimport com.mx.josesaid.develop.clientes.application.Comandos.NuevoConsentimiento;\nimport com.mx.josesaid.develop.clientes.domain.Consentimiento;\nimport com.mx.josesaid.develop.clientes.infrastructure.persistence.ConsentimientoRepository;\nimport com.mx.josesaid.develop.clientes.infrastructure.persistence.ContactoRepository;\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.util.Map;\nimport java.util.UUID;\nimport org.springframework.stereotype.Service;\nimport org.springframework.transaction.annotation.Transactional;\n\n/** Registra y revoca consentimientos de contactos. */\n@Service\n@Transactional\npublic class ConsentimientoService {\n\n    private final ContactoRepository contactos;\n    private final ConsentimientoRepository consentimientos;\n    private final RegistradorEventos eventos;\n    private final Clock reloj;\n\n    /** Recibe los repositorios de contactos y consentimientos, y el reloj. */\n    public ConsentimientoService(ContactoRepository contactos, ConsentimientoRepository consentimientos,\n                                 RegistradorEventos eventos, Clock reloj) {\n        this.contactos = contactos;\n        this.consentimientos = consentimientos;\n        this.eventos = eventos;\n        this.reloj = reloj;\n    }\n\n    /** Registra el consentimiento de un contacto para una finalidad. Falla si el contacto no existe. */\n    public Consentimiento otorgar(UUID contactoId, NuevoConsentimiento cmd) {\n        if (!contactos.existsById(contactoId)) {\n            throw new EntidadNoEncontradaException(\"contacto\", contactoId);\n        }\n        return consentimientos.save(Consentimiento.otorgado(UUID.randomUUID(), contactoId, cmd.finalidad(),\n                cmd.fechaOtorgado(), cmd.medio(), cmd.vigencia(), Instant.now(reloj)));\n    }\n\n    /** Idempotente: el evento ConsentimientoRevocado se emite solo la primera vez. */\n    public Consentimiento revocar(UUID consentimientoId) {\n        Consentimiento consentimiento = consentimientos.findById(consentimientoId)\n                .orElseThrow(() -> new EntidadNoEncontradaException(\"consentimiento\", consentimientoId));\n        if (consentimiento.revocar(Instant.now(reloj))) {\n            eventos.registrar(\"consentimiento\", consentimientoId, \"ConsentimientoRevocado\", Map.of(\n                    \"consentimientoId\", consentimientoId.toString(),\n                    \"contactoId\", consentimiento.getContactoId().toString(),\n                    \"finalidad\", consentimiento.getFinalidad()));\n        }\n        return consentimiento;\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/application/DetectorDuplicados.java": "package com.mx.josesaid.develop.clientes.application;\n\nimport com.mx.josesaid.develop.clientes.domain.EstatusCliente;\nimport com.mx.josesaid.develop.clientes.infrastructure.crypto.IndiceHash;\nimport com.mx.josesaid.develop.clientes.infrastructure.persistence.ClienteRepository;\nimport com.mx.josesaid.develop.clientes.infrastructure.persistence.ContactoRepository;\nimport com.mx.josesaid.develop.clientes.infrastructure.persistence.ProspectoRepository;\nimport io.micrometer.core.instrument.MeterRegistry;\nimport java.util.ArrayList;\nimport java.util.List;\nimport org.springframework.stereotype.Component;\n\n/**\n * Reglas de duplicados:\n * 1. RFC igual a un cliente no dado de baja: se rechaza siempre (ConflictoRfcException).\n * 2. Correo, nombre o razón social parecidos: se pide confirmación (DuplicadoPosibleException).\n */\n@Component\npublic class DetectorDuplicados {\n\n    static final String METRICA_DUPLICADOS = \"clientes.duplicados.detectados\";\n\n    private final ClienteRepository clientes;\n    private final ProspectoRepository prospectos;\n    private final ContactoRepository contactos;\n    private final MeterRegistry metricas;\n\n    /** Recibe los repositorios y las métricas de duplicados. */\n    public DetectorDuplicados(ClienteRepository clientes, ProspectoRepository prospectos,\n                              ContactoRepository contactos, MeterRegistry metricas) {\n        this.clientes = clientes;\n        this.prospectos = prospectos;\n        this.contactos = contactos;\n        this.metricas = metricas;\n    }\n\n    /** Rechaza el RFC si ya pertenece a un cliente que no está dado de baja. Cuenta el hallazgo en la métrica. */\n    public void validarRfcUnico(String rfc) {\n        if (rfc == null) {\n            return;\n        }\n        clientes.findFirstByRfcHashAndEstatusNot(IndiceHash.rfc(rfc), EstatusCliente.BAJA)\n                .ifPresent(existente -> {\n                    metricas.counter(METRICA_DUPLICADOS, \"criterio\", \"rfc\").increment();\n                    throw new ConflictoRfcException(existente.getId());\n                });\n    }\n\n    /** Busca coincidencias parciales por correo y por nombre o razón social. */\n    public void validarPosibles(String correo, String nombre, boolean confirmado) {\n        List<Coincidencia> coincidencias = new ArrayList<>();\n\n        String correoHash = IndiceHash.correo(correo);\n        prospectos.findByCorreoHash(correoHash)\n                .forEach(p -> coincidencias.add(new Coincidencia(\"correo\", \"prospecto\", p.getId())));\n        contactos.findByCorreoHash(correoHash)\n                .forEach(c -> coincidencias.add(new Coincidencia(\"correo\", \"contacto\", c.getId())));\n\n        if (nombre != null && !nombre.isBlank()) {\n            prospectos.findByNombreHash(IndiceHash.nombre(nombre))\n                    .forEach(p -> coincidencias.add(new Coincidencia(\"nombre\", \"prospecto\", p.getId())));\n            clientes.findByRazonSocialIgnoreCase(nombre.trim())\n                    .forEach(c -> coincidencias.add(new Coincidencia(\"razon_social\", \"cliente\", c.getId())));\n        }\n\n        if (coincidencias.isEmpty()) {\n            return;\n        }\n        metricas.counter(METRICA_DUPLICADOS, \"criterio\", \"posible\").increment();\n        if (!confirmado) {\n            throw new DuplicadoPosibleException(coincidencias);\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/application/DuplicadoPosibleException.java": "package com.mx.josesaid.develop.clientes.application;\n\nimport java.util.List;\n\n/** Existen coincidencias parciales (correo o nombre) y la alta no fue confirmada con confirmarDuplicado=true. */\npublic class DuplicadoPosibleException extends RuntimeException {\n\n    private final List<Coincidencia> coincidencias;\n\n    /** Se lanza cuando hay coincidencias parciales y el usuario aún no confirmó. Guarda las coincidencias para mostrarlas. */\n    public DuplicadoPosibleException(List<Coincidencia> coincidencias) {\n        super(\"Se encontraron registros posiblemente duplicados\");\n        this.coincidencias = List.copyOf(coincidencias);\n    }\n\n    /** Devuelve las coincidencias encontradas. */\n    public List<Coincidencia> getCoincidencias() {\n        return coincidencias;\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/application/EntidadNoEncontradaException.java": "package com.mx.josesaid.develop.clientes.application;\n\nimport java.util.UUID;\n\n/** Se lanza cuando no existe el recurso pedido. */\npublic class EntidadNoEncontradaException extends RuntimeException {\n\n    /** Crea la excepción indicando el tipo de entidad y su id. */\n    public EntidadNoEncontradaException(String tipo, UUID id) {\n        super(\"No existe \" + tipo + \" con id \" + id);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/application/InteraccionService.java": "package com.mx.josesaid.develop.clientes.application;\n\nimport com.mx.josesaid.develop.clientes.application.Comandos.NuevaInteraccion;\nimport com.mx.josesaid.develop.clientes.domain.Interaccion;\nimport com.mx.josesaid.develop.clientes.infrastructure.persistence.ClienteRepository;\nimport com.mx.josesaid.develop.clientes.infrastructure.persistence.InteraccionRepository;\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.util.UUID;\nimport org.springframework.data.domain.Page;\nimport org.springframework.data.domain.Pageable;\nimport org.springframework.stereotype.Service;\nimport org.springframework.transaction.annotation.Transactional;\n\n/** Registra y lista interacciones comerciales de los clientes. */\n@Service\n@Transactional\npublic class InteraccionService {\n\n    private final ClienteRepository clientes;\n    private final InteraccionRepository interacciones;\n    private final Clock reloj;\n\n    /** Recibe los repositorios, el reloj de la aplicación. */\n    public InteraccionService(ClienteRepository clientes, InteraccionRepository interacciones, Clock reloj) {\n        this.clientes = clientes;\n        this.interacciones = interacciones;\n        this.reloj = reloj;\n    }\n\n    /** Registra una interacción con un cliente. El responsable es el usuario que la registra. Falla si el cliente no existe. */\n    public Interaccion registrar(UUID clienteId, NuevaInteraccion cmd, UUID responsableId) {\n        verificarCliente(clienteId);\n        return interacciones.save(Interaccion.nueva(UUID.randomUUID(), clienteId, cmd.tipo(), cmd.fecha(),\n                responsableId, cmd.resumen(), Instant.now(reloj)));\n    }\n\n    /** Lista las interacciones de un cliente, paginadas. */\n    @Transactional(readOnly = true)\n    public Page<Interaccion> listar(UUID clienteId, Pageable pageable) {\n        verificarCliente(clienteId);\n        return interacciones.findByClienteId(clienteId, pageable);\n    }\n\n    /** Verifica que el cliente exista antes de registrar o listar sus interacciones. */\n    private void verificarCliente(UUID clienteId) {\n        if (!clientes.existsById(clienteId)) {\n            throw new EntidadNoEncontradaException(\"cliente\", clienteId);\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/application/MetricasService.java": "package com.mx.josesaid.develop.clientes.application;\n\nimport com.mx.josesaid.develop.clientes.domain.EstatusProspecto;\nimport com.mx.josesaid.develop.clientes.infrastructure.persistence.ProspectoRepository;\nimport java.time.Instant;\nimport java.time.YearMonth;\nimport java.time.ZoneId;\nimport org.springframework.beans.factory.annotation.Value;\nimport org.springframework.stereotype.Service;\nimport org.springframework.transaction.annotation.Transactional;\n\n/** Calcula métricas comerciales a partir de los prospectos convertidos. */\n@Service\npublic class MetricasService {\n\n    private final ProspectoRepository prospectos;\n    private final ZoneId zona;\n\n    /** Recibe el repositorio de prospectos y la zona horaria del negocio. */\n    public MetricasService(ProspectoRepository prospectos, @Value(\"${app.zona-presentacion}\") String zona) {\n        this.prospectos = prospectos;\n        this.zona = ZoneId.of(zona);\n    }\n\n    /** Prospectos convertidos en el mes indicado. El mes se interpreta en la zona de presentación. */\n    @Transactional(readOnly = true)\n    public long conversionesDelMes(YearMonth mes) {\n        Instant desde = mes.atDay(1).atStartOfDay(zona).toInstant();\n        Instant hasta = mes.plusMonths(1).atDay(1).atStartOfDay(zona).toInstant();\n        return prospectos.countByEstatusAndFechaConversionGreaterThanEqualAndFechaConversionLessThan(\n                EstatusProspecto.CONVERTIDO, desde, hasta);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/application/Normalizacion.java": "package com.mx.josesaid.develop.clientes.application;\n\nimport java.util.Locale;\n\n/** Normalización de datos antes de guardarlos o compararlos. */\nfinal class Normalizacion {\n\n    /** Clase de utilidad; no se instancia. */\n    private Normalizacion() {\n    }\n\n    /** RFC en mayúsculas y sin espacios. Devuelve null si el valor está vacío. */\n    static String rfc(String valor) {\n        if (valor == null || valor.isBlank()) {\n            return null;\n        }\n        return valor.trim().toUpperCase(Locale.ROOT);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/application/ProspectoService.java": "package com.mx.josesaid.develop.clientes.application;\n\nimport com.mx.josesaid.develop.clientes.domain.FechasNegocio;\nimport com.mx.josesaid.develop.clientes.application.Comandos.ConvertirProspecto;\nimport com.mx.josesaid.develop.clientes.application.Comandos.NuevoProspecto;\nimport com.mx.josesaid.develop.clientes.domain.Cliente;\nimport com.mx.josesaid.develop.clientes.domain.Contacto;\nimport com.mx.josesaid.develop.clientes.domain.EstatusProspecto;\nimport com.mx.josesaid.develop.clientes.domain.Prospecto;\nimport com.mx.josesaid.develop.clientes.infrastructure.persistence.ClienteRepository;\nimport com.mx.josesaid.develop.clientes.infrastructure.persistence.ContactoRepository;\nimport com.mx.josesaid.develop.clientes.infrastructure.persistence.ProspectoRepository;\nimport io.micrometer.core.instrument.MeterRegistry;\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.util.Map;\nimport java.util.UUID;\nimport org.springframework.stereotype.Service;\nimport org.springframework.transaction.annotation.Transactional;\n\n/** Lógica de negocio de prospectos: registro, cambios de estatus y conversión a cliente. */\n@Service\n@Transactional\npublic class ProspectoService {\n\n    private final ProspectoRepository prospectos;\n    private final ClienteRepository clientes;\n    private final ContactoRepository contactos;\n    private final DetectorDuplicados duplicados;\n    private final RegistradorEventos eventos;\n    private final MeterRegistry metricas;\n    private final Clock reloj;\n\n    /** Recibe los repositorios, el detector de duplicados, el registrador de eventos, las métricas y el reloj. */\n    public ProspectoService(ProspectoRepository prospectos, ClienteRepository clientes, ContactoRepository contactos,\n                            DetectorDuplicados duplicados, RegistradorEventos eventos,\n                            MeterRegistry metricas, Clock reloj) {\n        this.prospectos = prospectos;\n        this.clientes = clientes;\n        this.contactos = contactos;\n        this.duplicados = duplicados;\n        this.eventos = eventos;\n        this.metricas = metricas;\n        this.reloj = reloj;\n    }\n\n    /** Registra un prospecto. Valida el RFC y los posibles duplicados antes de guardarlo. */\n    public Prospecto crear(NuevoProspecto cmd) {\n        String rfc = Normalizacion.rfc(cmd.rfc());\n        duplicados.validarRfcUnico(rfc);\n        duplicados.validarPosibles(cmd.correo(), cmd.nombre(), cmd.confirmarDuplicado());\n\n        Prospecto guardado = prospectos.save(\n                Prospecto.nuevo(UUID.randomUUID(), cmd.nombre(), cmd.correo(), rfc, cmd.fuente(),\n                        FechasNegocio.hoy(reloj), Instant.now(reloj)));\n        metricas.counter(\"clientes.altas\", \"tipo\", \"prospecto\").increment();\n        return guardado;\n    }\n\n    /** Devuelve un prospecto por id o lanza EntidadNoEncontradaException. */\n    @Transactional(readOnly = true)\n    public Prospecto obtener(UUID id) {\n        return prospectos.findById(id).orElseThrow(() -> new EntidadNoEncontradaException(\"prospecto\", id));\n    }\n\n    /** Idempotente: repetir el estatus actual no hace cambios. CONVERTIDO solo se alcanza con convertir(). */\n    public Prospecto cambiarEstatus(UUID id, EstatusProspecto destino) {\n        Prospecto prospecto = obtener(id);\n        prospecto.cambiarEstatus(destino, Instant.now(reloj));\n        return prospecto;\n    }\n\n    /**\n     * Convierte un prospecto CALIFICADO en cliente ACTIVO con contacto principal.\n     * Idempotente: si el prospecto ya está CONVERTIDO devuelve el cliente existente.\n     */\n    public Cliente convertir(UUID prospectoId, ConvertirProspecto cmd) {\n        Prospecto prospecto = obtener(prospectoId);\n        if (prospecto.getEstatus() == EstatusProspecto.CONVERTIDO) {\n            return clientes.findFirstByProspectoId(prospectoId)\n                    .orElseThrow(() -> new IllegalStateException(\"Prospecto convertido sin cliente asociado: \" + prospectoId));\n        }\n\n        String rfc = Normalizacion.rfc(cmd.rfc());\n        duplicados.validarRfcUnico(rfc);\n\n        Instant ahora = Instant.now(reloj);\n        UUID clienteId = UUID.randomUUID();\n        UUID contactoId = UUID.randomUUID();\n        Cliente cliente = clientes.save(\n                Cliente.nuevo(clienteId, cmd.razonSocial(), rfc, prospecto.getId(), FechasNegocio.hoy(reloj), ahora));\n        contactos.save(Contacto.nuevo(contactoId, clienteId, cmd.contactoPrincipal().nombre(),\n                cmd.contactoPrincipal().correo(), cmd.contactoPrincipal().rol(), true, ahora));\n        prospecto.marcarConvertido(ahora);\n\n        eventos.registrar(\"cliente\", clienteId, \"ClienteCreado\", Map.of(\n                \"clienteId\", clienteId.toString(),\n                \"prospectoId\", prospectoId.toString(),\n                \"contactoPrincipalId\", contactoId.toString(),\n                \"estatus\", cliente.getEstatus().name()));\n        metricas.counter(\"clientes.conversiones\").increment();\n        return cliente;\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/application/RegistradorEventos.java": "package com.mx.josesaid.develop.clientes.application;\n\nimport com.mx.josesaid.develop.clientes.infrastructure.outbox.OutboxEvento;\nimport com.mx.josesaid.develop.clientes.infrastructure.outbox.OutboxRepository;\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.util.LinkedHashMap;\nimport java.util.Map;\nimport java.util.UUID;\nimport org.springframework.stereotype.Component;\nimport tools.jackson.databind.ObjectMapper;\n\n/**\n * Escribe el evento en la tabla outbox. Debe llamarse dentro de la misma transacción que el cambio de estado.\n * El sobre del evento incluye eventoId, tipoEvento y ocurridoEn, además de los datos propios del evento.\n */\n@Component\npublic class RegistradorEventos {\n\n    private final OutboxRepository outbox;\n    private final ObjectMapper json;\n    private final Clock reloj;\n\n    /** Recibe el outbox, el serializador JSON y el reloj. */\n    public RegistradorEventos(OutboxRepository outbox, ObjectMapper json, Clock reloj) {\n        this.outbox = outbox;\n        this.json = json;\n        this.reloj = reloj;\n    }\n\n    /** Guarda un evento de dominio en el outbox, dentro de la misma transacción que el cambio. Así el evento nunca se pierde si el cambio se confirma. */\n    public void registrar(String tipoAgregado, UUID agregadoId, String tipoEvento, Map<String, Object> datos) {\n        UUID eventoId = UUID.randomUUID();\n        Instant ahora = Instant.now(reloj);\n\n        Map<String, Object> sobre = new LinkedHashMap<>();\n        sobre.put(\"eventoId\", eventoId.toString());\n        sobre.put(\"tipoEvento\", tipoEvento);\n        sobre.put(\"ocurridoEn\", ahora.toString());\n        sobre.putAll(datos);\n\n        String payload = json.writeValueAsString(sobre);\n        outbox.save(new OutboxEvento(eventoId, tipoAgregado, agregadoId, tipoEvento, payload, ahora));\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/application/ReglaNegocioException.java": "package com.mx.josesaid.develop.clientes.application;\n\n/** Una regla de negocio impide la operación y no es un conflicto de estado (responde 422). */\npublic class ReglaNegocioException extends RuntimeException {\n\n    /** Se lanza cuando una regla de negocio no se cumple. El mensaje se muestra al usuario. */\n    public ReglaNegocioException(String mensaje) {\n        super(mensaje);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/config/CryptoConfig.java": "package com.mx.josesaid.develop.clientes.config;\n\nimport com.mx.josesaid.develop.clientes.infrastructure.crypto.ClavesCripto;\nimport java.util.HashMap;\nimport java.util.Map;\nimport java.util.Base64;\nimport org.springframework.boot.context.properties.EnableConfigurationProperties;\nimport org.springframework.context.annotation.Configuration;\n\n/** Valida las claves al arrancar. Si faltan o no miden 32 bytes, la aplicación no inicia. */\n@Configuration\n@EnableConfigurationProperties(CryptoProperties.class)\npublic class CryptoConfig {\n\n    private static final int LONGITUD_CLAVE = 32;\n    private static final int VERSION_UNICA = 1;\n\n    /** Carga las claves de cifrado al arrancar, antes de que Hibernate use los convertidores. */\n    public CryptoConfig(CryptoProperties propiedades) {\n        Map<Integer, byte[]> claves = clavesCifrado(propiedades);\n        int version = propiedades.versionActiva() == null ? VERSION_UNICA : propiedades.versionActiva();\n        ClavesCripto.configurar(\n                claves,\n                version,\n                decodificar(\"app.crypto.clave-indice (CRYPTO_CLAVE_INDICE)\", propiedades.claveIndice()));\n    }\n\n    /** Convierte las claves configuradas en bytes, verificando que cada una tenga 32 bytes. */\n    private static Map<Integer, byte[]> clavesCifrado(CryptoProperties propiedades) {\n        Map<Integer, byte[]> claves = new HashMap<>();\n        if (propiedades.clavesCifrado() != null && !propiedades.clavesCifrado().isBlank()) {\n            for (String entrada : propiedades.clavesCifrado().split(\",\")) {\n                String[] partes = entrada.trim().split(\":\", 2);\n                if (partes.length != 2) {\n                    throw new IllegalStateException(\"CRYPTO_CLAVES_CIFRADO debe tener el formato N:base64,N:base64\");\n                }\n                int numero = Integer.parseInt(partes[0].trim());\n                if (claves.put(numero, decodificar(\"CRYPTO_CLAVES_CIFRADO versión \" + numero, partes[1])) != null) {\n                    throw new IllegalStateException(\"La versión \" + numero + \" de clave aparece más de una vez\");\n                }\n            }\n        } else {\n            claves.put(VERSION_UNICA,\n                    decodificar(\"app.crypto.clave-cifrado (CRYPTO_CLAVE_CIFRADO)\", propiedades.claveCifrado()));\n        }\n        return claves;\n    }\n\n    /** Decodifica una clave en Base64 y verifica su longitud. Si no es válida, el arranque falla. */\n    private static byte[] decodificar(String nombre, String valor) {\n        if (valor == null || valor.isBlank()) {\n            throw new IllegalStateException(\"Falta \" + nombre);\n        }\n        byte[] clave = Base64.getDecoder().decode(valor.trim());\n        if (clave.length != LONGITUD_CLAVE) {\n            throw new IllegalStateException(nombre + \" debe ser de 32 bytes en Base64; recibió \" + clave.length);\n        }\n        return clave;\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/config/CryptoProperties.java": "package com.mx.josesaid.develop.clientes.config;\n\nimport org.springframework.boot.context.properties.ConfigurationProperties;\n\n/**\n * Claves de cifrado. {@code claveCifrado} es la clave única previa (versión 1); {@code clavesCifrado} es la\n * lista {@code N:base64,N:base64} de todas las versiones y {@code versionActiva} la que se usa para cifrar.\n * Vienen de CRYPTO_CLAVE_CIFRADO, CRYPTO_CLAVES_CIFRADO, CRYPTO_VERSION_ACTIVA y CRYPTO_CLAVE_INDICE.\n  * @param claveCifrado clave cifrado, de tipo {@code String}.\n  * @param clavesCifrado claves cifrado, de tipo {@code String}.\n  * @param versionActiva version activa, de tipo {@code Integer}.\n  * @param claveIndice clave indice, de tipo {@code String}.\n */\n@ConfigurationProperties(prefix = \"app.crypto\")\npublic record CryptoProperties(String claveCifrado, String clavesCifrado, Integer versionActiva, String claveIndice) {\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/config/SeguridadConfig.java": "package com.mx.josesaid.develop.clientes.config;\n\nimport org.springframework.security.access.hierarchicalroles.RoleHierarchy;\nimport org.springframework.security.access.hierarchicalroles.RoleHierarchyImpl;\n\nimport com.mx.josesaid.develop.clientes.seguridad.EntradaNoAutorizada;\n\nimport com.mx.josesaid.develop.clientes.seguridad.RevocacionSesiones;\nimport com.mx.josesaid.develop.clientes.seguridad.ValidadorRevocacion;\nimport org.springframework.security.oauth2.core.DelegatingOAuth2TokenValidator;\nimport org.springframework.security.oauth2.jwt.JwtValidators;\nimport org.springframework.security.oauth2.jwt.JwtDecoder;\nimport org.springframework.security.oauth2.jwt.NimbusJwtDecoder;\n\nimport org.springframework.beans.factory.annotation.Value;\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\nimport org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;\nimport org.springframework.security.config.annotation.web.builders.HttpSecurity;\nimport org.springframework.security.config.http.SessionCreationPolicy;\nimport org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationConverter;\nimport org.springframework.security.oauth2.server.resource.authentication.JwtGrantedAuthoritiesConverter;\nimport org.springframework.security.web.SecurityFilterChain;\n\n/**\n * API sin estado. Los roles salen del claim configurado en app.seguridad.claim-roles y\n * se convierten en autoridades ROLE_*. Salud, info y métricas son públicas dentro de la red interna.\n */\n@Configuration\n@EnableMethodSecurity\npublic class SeguridadConfig {\n\n    /** Cadena de seguridad de la API sin estado: exige JWT válido en todo, excepto salud, info y métricas. Los roles salen del claim configurado. */\n    @Bean\n    public SecurityFilterChain cadenaSeguridad(HttpSecurity http,\n                                               @Value(\"${app.seguridad.claim-roles}\") String claimRoles) throws Exception {\n        JwtGrantedAuthoritiesConverter autoridades = new JwtGrantedAuthoritiesConverter();\n        autoridades.setAuthoritiesClaimName(claimRoles);\n        autoridades.setAuthorityPrefix(\"ROLE_\");\n\n        JwtAuthenticationConverter convertidor = new JwtAuthenticationConverter();\n        convertidor.setJwtGrantedAuthoritiesConverter(autoridades);\n\n        return http\n                .csrf(csrf -> csrf.disable())\n                .sessionManagement(sesion -> sesion.sessionCreationPolicy(SessionCreationPolicy.STATELESS))\n                .authorizeHttpRequests(auth -> auth\n                        .requestMatchers(\"/actuator/health\", \"/actuator/info\", \"/actuator/prometheus\").permitAll()\n                        .anyRequest().authenticated())\n                .oauth2ResourceServer(oauth -> oauth.authenticationEntryPoint(new EntradaNoAutorizada()).jwt(jwt -> jwt.jwtAuthenticationConverter(convertidor)))\n                .build();\n    }\n\n    /** Valida los tokens por JWKS y rechaza las sesiones cerradas en usuarios-accesos-ms. */\n    @Bean\n    JwtDecoder jwtDecoder(@Value(\"${spring.security.oauth2.resourceserver.jwt.jwk-set-uri}\") String jwksUri,\n                          RevocacionSesiones revocaciones) {\n        var decoder = NimbusJwtDecoder.withJwkSetUri(jwksUri).build();\n        decoder.setJwtValidator(new DelegatingOAuth2TokenValidator<>(JwtValidators.createDefault(),\n                new ValidadorRevocacion(revocaciones)));\n        return decoder;\n    }\n\n    /** ADMIN puede hacer todo: hereda todos los roles de negocio. */\n    @Bean\n    RoleHierarchy jerarquiaRoles() {\n        return RoleHierarchyImpl.withDefaultRolePrefix()\n                .role(\"ADMIN\").implies(\"FINANZAS\", \"CONTADOR\", \"VENTAS\", \"COMPRAS\", \"ALMACEN\", \"OPERACIONES\", \"CALIDAD\", \"DIRECCION\", \"LEGAL\", \"JEFE_AREA\")\n                .build();\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/config/TiempoConfig.java": "package com.mx.josesaid.develop.clientes.config;\n\nimport java.time.Clock;\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\n\n/** Todo el sistema calcula el tiempo con este reloj en UTC. La conversión a zona local ocurre solo en la capa api. */\n@Configuration\npublic class TiempoConfig {\n\n    /** Reloj del sistema en UTC, usado para todas las fechas de negocio. */\n    @Bean\n    public Clock reloj() {\n        return Clock.systemUTC();\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/domain/Cliente.java": "package com.mx.josesaid.develop.clientes.domain;\n\nimport com.mx.josesaid.develop.clientes.infrastructure.crypto.CampoCifradoConverter;\nimport com.mx.josesaid.develop.clientes.infrastructure.crypto.IndiceHash;\nimport jakarta.persistence.Column;\nimport jakarta.persistence.Convert;\nimport jakarta.persistence.Entity;\nimport jakarta.persistence.EnumType;\nimport jakarta.persistence.Enumerated;\nimport jakarta.persistence.Id;\nimport jakarta.persistence.Table;\nimport jakarta.persistence.Version;\nimport java.time.Instant;\nimport java.time.LocalDate;\nimport java.util.UUID;\n\n/** Cliente activo de la empresa. Se crea desde un prospecto convertido o con alta directa. */\n@Entity\n@Table(name = \"cliente\")\npublic class Cliente {\n\n    @Id\n    private UUID id;\n\n    @Column(name = \"razon_social\", nullable = false, length = 250)\n    private String razonSocial;\n\n    @Convert(converter = CampoCifradoConverter.class)\n    @Column(name = \"rfc_cifrado\", nullable = false)\n    private String rfc;\n\n    @Column(name = \"rfc_hash\", nullable = false, length = 64)\n    private String rfcHash;\n\n    @Enumerated(EnumType.STRING)\n    @Column(name = \"estatus\", nullable = false, length = 20)\n    private EstatusCliente estatus;\n\n    @Column(name = \"prospecto_id\")\n    private UUID prospectoId;\n\n    @Column(name = \"fecha_alta\", nullable = false)\n    private LocalDate fechaAlta;\n\n    @Column(name = \"created_at\", nullable = false)\n    private Instant createdAt;\n\n    @Column(name = \"updated_at\", nullable = false)\n    private Instant updatedAt;\n\n    @Version\n    @Column(name = \"version\", nullable = false)\n    private long version;\n\n    /** Constructor exigido por JPA. No se usa en el código de la aplicación. */\n    protected Cliente() {\n    }\n\n    /** Crea un cliente en estatus ACTIVO. */\n    public static Cliente nuevo(UUID id, String razonSocial, String rfc, UUID prospectoId,\n                                LocalDate fechaAlta, Instant ahora) {\n        Cliente c = new Cliente();\n        c.id = id;\n        c.razonSocial = razonSocial.trim();\n        c.rfc = rfc;\n        c.rfcHash = IndiceHash.rfc(rfc);\n        c.estatus = EstatusCliente.ACTIVO;\n        c.prospectoId = prospectoId;\n        c.fechaAlta = fechaAlta;\n        c.createdAt = ahora;\n        c.updatedAt = ahora;\n        return c;\n    }\n\n    /** Cambia la razón social tras validar que no esté vacía. */\n    public void actualizarRazonSocial(String nuevaRazonSocial, Instant ahora) {\n        this.razonSocial = nuevaRazonSocial.trim();\n        this.updatedAt = ahora;\n    }\n\n    /** Cambia el estatus si la transición está permitida. */\n    public void cambiarEstatus(EstatusCliente destino, Instant ahora) {\n        if (estatus == destino) {\n            return;\n        }\n        if (!estatus.puedePasarA(destino)) {\n            throw new TransicionInvalidaException(\"Un cliente en BAJA no puede reactivarse\");\n        }\n        estatus = destino;\n        updatedAt = ahora;\n    }\n\n    /** Devuelve el identificador. */\n    public UUID getId() {\n        return id;\n    }\n\n    /** Devuelve la razón social. */\n    public String getRazonSocial() {\n        return razonSocial;\n    }\n\n    /** Devuelve el RFC. */\n    public String getRfc() {\n        return rfc;\n    }\n\n    /** Devuelve el estatus. */\n    public EstatusCliente getEstatus() {\n        return estatus;\n    }\n\n    /** Devuelve el id del prospecto del que se originó, si aplica. */\n    public UUID getProspectoId() {\n        return prospectoId;\n    }\n\n    /** Devuelve la fecha de alta. */\n    public LocalDate getFechaAlta() {\n        return fechaAlta;\n    }\n\n    /** Devuelve la versión para control de concurrencia optimista. */\n    public long getVersion() {\n        return version;\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/domain/Consentimiento.java": "package com.mx.josesaid.develop.clientes.domain;\n\nimport jakarta.persistence.Column;\nimport jakarta.persistence.Entity;\nimport jakarta.persistence.EnumType;\nimport jakarta.persistence.Enumerated;\nimport jakarta.persistence.Id;\nimport jakarta.persistence.Table;\nimport java.time.Instant;\nimport java.time.LocalDate;\nimport java.util.UUID;\n\n/** Consentimiento de un contacto para una finalidad concreta. Se conserva aunque se revoque. */\n@Entity\n@Table(name = \"consentimiento\")\npublic class Consentimiento {\n\n    @Id\n    private UUID id;\n\n    @Column(name = \"contacto_id\", nullable = false)\n    private UUID contactoId;\n\n    @Column(name = \"finalidad\", nullable = false, length = 100)\n    private String finalidad;\n\n    @Column(name = \"fecha_otorgado\", nullable = false)\n    private Instant fechaOtorgado;\n\n    @Enumerated(EnumType.STRING)\n    @Column(name = \"medio\", nullable = false, length = 20)\n    private MedioConsentimiento medio;\n\n    @Column(name = \"vigencia\")\n    private LocalDate vigencia;\n\n    @Column(name = \"revocado_at\")\n    private Instant revocadoAt;\n\n    @Column(name = \"created_at\", nullable = false)\n    private Instant createdAt;\n\n    /** Constructor exigido por JPA. No se usa en el código de la aplicación. */\n    protected Consentimiento() {\n    }\n\n    /** Crea un consentimiento otorgado, con su vigencia. */\n    public static Consentimiento otorgado(UUID id, UUID contactoId, String finalidad, Instant fechaOtorgado,\n                                          MedioConsentimiento medio, LocalDate vigencia, Instant ahora) {\n        Consentimiento c = new Consentimiento();\n        c.id = id;\n        c.contactoId = contactoId;\n        c.finalidad = finalidad.trim();\n        c.fechaOtorgado = fechaOtorgado;\n        c.medio = medio;\n        c.vigencia = vigencia;\n        c.createdAt = ahora;\n        return c;\n    }\n\n    /**\n     * Revoca el consentimiento. Devuelve true solo la primera vez; las siguientes son no-op.\n     */\n    public boolean revocar(Instant ahora) {\n        if (revocadoAt != null) {\n            return false;\n        }\n        revocadoAt = ahora;\n        return true;\n    }\n\n    /** Vigente si no fue revocado y su vigencia (si existe) no ha vencido. */\n    public boolean estaVigente(LocalDate hoy) {\n        return revocadoAt == null && (vigencia == null || !hoy.isAfter(vigencia));\n    }\n\n    /** Devuelve el identificador. */\n    public UUID getId() {\n        return id;\n    }\n\n    /** Devuelve el id del contacto. */\n    public UUID getContactoId() {\n        return contactoId;\n    }\n\n    /** Devuelve la finalidad. */\n    public String getFinalidad() {\n        return finalidad;\n    }\n\n    /** Devuelve la fecha en que se otorgó. */\n    public Instant getFechaOtorgado() {\n        return fechaOtorgado;\n    }\n\n    /** Devuelve el medio por el que se otorgó. */\n    public MedioConsentimiento getMedio() {\n        return medio;\n    }\n\n    /** Devuelve la fecha hasta la que es vigente. */\n    public LocalDate getVigencia() {\n        return vigencia;\n    }\n\n    /** Devuelve el momento de la revocación, o nulo si sigue vigente. */\n    public Instant getRevocadoAt() {\n        return revocadoAt;\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/domain/Contacto.java": "package com.mx.josesaid.develop.clientes.domain;\n\nimport com.mx.josesaid.develop.clientes.infrastructure.crypto.CampoCifradoConverter;\nimport com.mx.josesaid.develop.clientes.infrastructure.crypto.IndiceHash;\nimport jakarta.persistence.Column;\nimport jakarta.persistence.Convert;\nimport jakarta.persistence.Entity;\nimport jakarta.persistence.EnumType;\nimport jakarta.persistence.Enumerated;\nimport jakarta.persistence.Id;\nimport jakarta.persistence.Table;\nimport jakarta.persistence.Version;\nimport java.time.Instant;\nimport java.util.UUID;\n\n/** Persona de contacto de un cliente. Un cliente tiene como máximo un contacto principal. */\n@Entity\n@Table(name = \"contacto\")\npublic class Contacto {\n\n    @Id\n    private UUID id;\n\n    @Column(name = \"cliente_id\", nullable = false)\n    private UUID clienteId;\n\n    @Convert(converter = CampoCifradoConverter.class)\n    @Column(name = \"nombre_cifrado\", nullable = false)\n    private String nombre;\n\n    @Convert(converter = CampoCifradoConverter.class)\n    @Column(name = \"correo_cifrado\", nullable = false)\n    private String correo;\n\n    @Column(name = \"correo_hash\", nullable = false, length = 64)\n    private String correoHash;\n\n    @Enumerated(EnumType.STRING)\n    @Column(name = \"rol\", nullable = false, length = 20)\n    private RolContacto rol;\n\n    @Column(name = \"principal\", nullable = false)\n    private boolean principal;\n\n    @Column(name = \"created_at\", nullable = false)\n    private Instant createdAt;\n\n    @Column(name = \"updated_at\", nullable = false)\n    private Instant updatedAt;\n\n    @Version\n    @Column(name = \"version\", nullable = false)\n    private long version;\n\n    /** Constructor exigido por JPA. No se usa en el código de la aplicación. */\n    protected Contacto() {\n    }\n\n    /** Crea un contacto del cliente. */\n    public static Contacto nuevo(UUID id, UUID clienteId, String nombre, String correo, RolContacto rol,\n                                 boolean principal, Instant ahora) {\n        Contacto c = new Contacto();\n        c.id = id;\n        c.clienteId = clienteId;\n        c.nombre = nombre.trim();\n        c.correo = correo.trim();\n        c.correoHash = IndiceHash.correo(correo);\n        c.rol = rol;\n        c.principal = principal;\n        c.createdAt = ahora;\n        c.updatedAt = ahora;\n        return c;\n    }\n\n    /** Quita la marca de principal. Se usa cuando otro contacto pasa a ser el principal. */\n    public void desmarcarPrincipal(Instant ahora) {\n        this.principal = false;\n        this.updatedAt = ahora;\n    }\n\n    /** Devuelve el identificador. */\n    public UUID getId() {\n        return id;\n    }\n\n    /** Devuelve el id del cliente. */\n    public UUID getClienteId() {\n        return clienteId;\n    }\n\n    /** Devuelve el nombre. */\n    public String getNombre() {\n        return nombre;\n    }\n\n    /** Devuelve el correo. */\n    public String getCorreo() {\n        return correo;\n    }\n\n    /** Devuelve el rol del contacto. */\n    public RolContacto getRol() {\n        return rol;\n    }\n\n    /** Indica si es el contacto principal. */\n    public boolean isPrincipal() {\n        return principal;\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/domain/EstatusCliente.java": "package com.mx.josesaid.develop.clientes.domain;\n\n/**\n * Estados de un cliente. ACTIVO y SUSPENDIDO se alternan entre sí; cualquier estado puede pasar a BAJA.\n * BAJA es terminal: un cliente dado de baja no se reactiva.\n */\npublic enum EstatusCliente {\n    ACTIVO,\n    SUSPENDIDO,\n    BAJA;\n\n    /** Indica si el cliente puede pasar al estatus indicado. Las transiciones no permitidas se rechazan. */\n    public boolean puedePasarA(EstatusCliente destino) {\n        if (this == destino) {\n            return true;\n        }\n        return this != BAJA;\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/domain/EstatusProspecto.java": "package com.mx.josesaid.develop.clientes.domain;\n\nimport java.util.EnumSet;\nimport java.util.Set;\n\n/**\n * Estados de un prospecto. Flujo: NUEVO -> CONTACTADO -> CALIFICADO -> CONVERTIDO.\n * PERDIDO se alcanza desde cualquier estado abierto. CONVERTIDO solo se alcanza por la operación de conversión.\n */\npublic enum EstatusProspecto {\n    NUEVO,\n    CONTACTADO,\n    CALIFICADO,\n    CONVERTIDO,\n    PERDIDO;\n\n    private static final Set<EstatusProspecto> ABIERTOS = EnumSet.of(NUEVO, CONTACTADO, CALIFICADO);\n\n    /** Indica si el prospecto sigue abierto, es decir, no está convertido ni descartado. */\n    public boolean esAbierto() {\n        return ABIERTOS.contains(this);\n    }\n\n    /** Indica si el cambio de estatus por PATCH es válido. Repetir el estatus actual siempre es válido (idempotente). */\n    public boolean puedePasarA(EstatusProspecto destino) {\n        if (this == destino) {\n            return true;\n        }\n        if (destino == CONVERTIDO) {\n            return false;\n        }\n        if (destino == PERDIDO) {\n            return esAbierto();\n        }\n        return switch (this) {\n            case NUEVO -> destino == CONTACTADO;\n            case CONTACTADO -> destino == CALIFICADO;\n            case CALIFICADO, CONVERTIDO, PERDIDO -> false;\n        };\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/domain/FechasNegocio.java": "package com.mx.josesaid.develop.clientes.domain;\n\nimport java.time.Clock;\nimport java.time.LocalDate;\nimport java.time.ZoneId;\n\n/**\n * Fechas de negocio (alta, registro) en la zona de operación. Los instantes siguen en UTC;\n * solo la fecha calendario se toma en hora de México, para que un alta a las 22:00 cuente como ese día.\n */\npublic final class FechasNegocio {\n\n    public static final ZoneId ZONA = ZoneId.of(\"America/Mexico_City\");\n\n    /** Clase de utilidad; no se instancia. */\n    private FechasNegocio() {\n    }\n\n    /** Devuelve la fecha de hoy en la zona de México. Así las fechas de alta no cambian de día a mitad de la madrugada por la zona UTC. */\n    public static LocalDate hoy(Clock reloj) {\n        return LocalDate.now(reloj.withZone(ZONA));\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/domain/Fuente.java": "package com.mx.josesaid.develop.clientes.domain;\n\n/** Origen de un prospecto. Se usa \"CAMPANA\" sin tilde; ver pendientes en el README. */\npublic enum Fuente {\n    CAMPANA,\n    REFERIDO,\n    EVENTO\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/domain/Interaccion.java": "package com.mx.josesaid.develop.clientes.domain;\n\nimport com.mx.josesaid.develop.clientes.infrastructure.crypto.CampoCifradoConverter;\nimport jakarta.persistence.Column;\nimport jakarta.persistence.Convert;\nimport jakarta.persistence.Entity;\nimport jakarta.persistence.EnumType;\nimport jakarta.persistence.Enumerated;\nimport jakarta.persistence.Id;\nimport jakarta.persistence.Table;\nimport java.time.Instant;\nimport java.util.UUID;\n\n/** Contacto o evento comercial registrado con un cliente: llamada, correo, reunión, etc. */\n@Entity\n@Table(name = \"interaccion\")\npublic class Interaccion {\n\n    @Id\n    private UUID id;\n\n    @Column(name = \"cliente_id\", nullable = false)\n    private UUID clienteId;\n\n    @Enumerated(EnumType.STRING)\n    @Column(name = \"tipo\", nullable = false, length = 20)\n    private TipoInteraccion tipo;\n\n    @Column(name = \"fecha\", nullable = false)\n    private Instant fecha;\n\n    @Column(name = \"responsable_id\", nullable = false)\n    private UUID responsableId;\n\n    @Convert(converter = CampoCifradoConverter.class)\n    @Column(name = \"resumen_cifrado\", nullable = false)\n    private String resumen;\n\n    @Column(name = \"created_at\", nullable = false)\n    private Instant createdAt;\n\n    /** Constructor exigido por JPA. No se usa en el código de la aplicación. */\n    protected Interaccion() {\n    }\n\n    /** Crea una interacción con su tipo, fecha y resumen. */\n    public static Interaccion nueva(UUID id, UUID clienteId, TipoInteraccion tipo, Instant fecha,\n                                    UUID responsableId, String resumen, Instant ahora) {\n        Interaccion i = new Interaccion();\n        i.id = id;\n        i.clienteId = clienteId;\n        i.tipo = tipo;\n        i.fecha = fecha;\n        i.responsableId = responsableId;\n        i.resumen = resumen.trim();\n        i.createdAt = ahora;\n        return i;\n    }\n\n    /** Devuelve el identificador. */\n    public UUID getId() {\n        return id;\n    }\n\n    /** Devuelve el id del cliente. */\n    public UUID getClienteId() {\n        return clienteId;\n    }\n\n    /** Devuelve el tipo de interacción. */\n    public TipoInteraccion getTipo() {\n        return tipo;\n    }\n\n    /** Devuelve la fecha y hora de la interacción en UTC. */\n    public Instant getFecha() {\n        return fecha;\n    }\n\n    /** Devuelve el id del usuario que la registró. */\n    public UUID getResponsableId() {\n        return responsableId;\n    }\n\n    /** Devuelve el resumen. */\n    public String getResumen() {\n        return resumen;\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/domain/MedioConsentimiento.java": "package com.mx.josesaid.develop.clientes.domain;\n\n/** Medio por el que se otorgó el consentimiento. Valores pendientes de confirmar por el área legal (ver README). */\npublic enum MedioConsentimiento {\n    FORMULARIO,\n    CORREO,\n    TELEFONO,\n    PRESENCIAL\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/domain/Prospecto.java": "package com.mx.josesaid.develop.clientes.domain;\n\nimport com.mx.josesaid.develop.clientes.infrastructure.crypto.CampoCifradoConverter;\nimport com.mx.josesaid.develop.clientes.infrastructure.crypto.IndiceHash;\nimport jakarta.persistence.Column;\nimport jakarta.persistence.Convert;\nimport jakarta.persistence.Entity;\nimport jakarta.persistence.EnumType;\nimport jakarta.persistence.Enumerated;\nimport jakarta.persistence.Id;\nimport jakarta.persistence.Table;\nimport jakarta.persistence.Version;\nimport java.time.Instant;\nimport java.time.LocalDate;\nimport java.util.UUID;\n\n/** Posible cliente que aún no se ha convertido. Pasa por estatus hasta convertirse en cliente. */\n@Entity\n@Table(name = \"prospecto\")\npublic class Prospecto {\n\n    @Id\n    private UUID id;\n\n    @Convert(converter = CampoCifradoConverter.class)\n    @Column(name = \"nombre_cifrado\", nullable = false)\n    private String nombre;\n\n    @Column(name = \"nombre_hash\", nullable = false, length = 64)\n    private String nombreHash;\n\n    @Convert(converter = CampoCifradoConverter.class)\n    @Column(name = \"correo_cifrado\", nullable = false)\n    private String correo;\n\n    @Column(name = \"correo_hash\", nullable = false, length = 64)\n    private String correoHash;\n\n    @Convert(converter = CampoCifradoConverter.class)\n    @Column(name = \"rfc_cifrado\")\n    private String rfc;\n\n    @Column(name = \"rfc_hash\", length = 64)\n    private String rfcHash;\n\n    @Enumerated(EnumType.STRING)\n    @Column(name = \"fuente\", nullable = false, length = 20)\n    private Fuente fuente;\n\n    @Enumerated(EnumType.STRING)\n    @Column(name = \"estatus\", nullable = false, length = 20)\n    private EstatusProspecto estatus;\n\n    @Column(name = \"fecha_registro\", nullable = false)\n    private LocalDate fechaRegistro;\n\n    @Column(name = \"fecha_conversion\")\n    private Instant fechaConversion;\n\n    @Column(name = \"created_at\", nullable = false)\n    private Instant createdAt;\n\n    @Column(name = \"updated_at\", nullable = false)\n    private Instant updatedAt;\n\n    @Version\n    @Column(name = \"version\", nullable = false)\n    private long version;\n\n    /** Constructor exigido por JPA. No se usa en el código de la aplicación. */\n    protected Prospecto() {\n    }\n\n    /** Crea un prospecto en estatus inicial y guarda huellas de búsqueda de su correo, nombre y RFC. */\n    public static Prospecto nuevo(UUID id, String nombre, String correo, String rfc, Fuente fuente,\n                                  LocalDate hoy, Instant ahora) {\n        Prospecto p = new Prospecto();\n        p.id = id;\n        p.nombre = nombre.trim();\n        p.nombreHash = IndiceHash.nombre(nombre);\n        p.correo = correo.trim();\n        p.correoHash = IndiceHash.correo(correo);\n        p.rfc = rfc;\n        p.rfcHash = rfc == null ? null : IndiceHash.rfc(rfc);\n        p.fuente = fuente;\n        p.estatus = EstatusProspecto.NUEVO;\n        p.fechaRegistro = hoy;\n        p.createdAt = ahora;\n        p.updatedAt = ahora;\n        return p;\n    }\n\n    /** Cambia el estatus por PATCH. Lanza TransicionInvalidaException si la transición no está permitida. */\n    public void cambiarEstatus(EstatusProspecto destino, Instant ahora) {\n        if (estatus == destino) {\n            return;\n        }\n        if (!estatus.puedePasarA(destino)) {\n            throw new TransicionInvalidaException(\"Transición de prospecto no permitida: \" + estatus + \" -> \" + destino);\n        }\n        estatus = destino;\n        updatedAt = ahora;\n    }\n\n    /** Solo un prospecto CALIFICADO puede convertirse. */\n    public void marcarConvertido(Instant ahora) {\n        if (estatus != EstatusProspecto.CALIFICADO) {\n            throw new TransicionInvalidaException(\"Solo un prospecto CALIFICADO puede convertirse\");\n        }\n        estatus = EstatusProspecto.CONVERTIDO;\n        fechaConversion = ahora;\n        updatedAt = ahora;\n    }\n\n    /** Devuelve el identificador. */\n    public UUID getId() {\n        return id;\n    }\n\n    /** Devuelve el nombre. */\n    public String getNombre() {\n        return nombre;\n    }\n\n    /** Devuelve el correo. */\n    public String getCorreo() {\n        return correo;\n    }\n\n    /** Devuelve el RFC. */\n    public String getRfc() {\n        return rfc;\n    }\n\n    /** Devuelve la fuente por la que llegó el prospecto. */\n    public Fuente getFuente() {\n        return fuente;\n    }\n\n    /** Devuelve el estatus. */\n    public EstatusProspecto getEstatus() {\n        return estatus;\n    }\n\n    /** Devuelve la fecha de registro. */\n    public LocalDate getFechaRegistro() {\n        return fechaRegistro;\n    }\n\n    /** Devuelve la fecha de conversión, o nula si no se ha convertido. */\n    public Instant getFechaConversion() {\n        return fechaConversion;\n    }\n\n    /** Devuelve la huella de búsqueda del correo, sin el correo en claro. */\n    public String getCorreoHash() {\n        return correoHash;\n    }\n\n    /** Devuelve la huella de búsqueda del nombre. */\n    public String getNombreHash() {\n        return nombreHash;\n    }\n\n    /** Devuelve la versión para control de concurrencia optimista. */\n    public long getVersion() {\n        return version;\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/domain/RolContacto.java": "package com.mx.josesaid.develop.clientes.domain;\n\n/** Rol del contacto dentro del cliente, por ejemplo compras o finanzas. */\npublic enum RolContacto {\n    COMPRAS,\n    PAGOS,\n    ASISTENCIA\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/domain/TipoInteraccion.java": "package com.mx.josesaid.develop.clientes.domain;\n\n/** Tipo de interacción comercial registrada con un cliente. */\npublic enum TipoInteraccion {\n    LLAMADA,\n    CORREO,\n    VISITA\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/domain/TransicionInvalidaException.java": "package com.mx.josesaid.develop.clientes.domain;\n\n/** Se lanza cuando un cambio de estatus viola las reglas de la máquina de estados. */\npublic class TransicionInvalidaException extends RuntimeException {\n\n    /** Se lanza cuando se pide un cambio de estatus no permitido. */\n    public TransicionInvalidaException(String mensaje) {\n        super(mensaje);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/infrastructure/crypto/CampoCifradoConverter.java": "package com.mx.josesaid.develop.clientes.infrastructure.crypto;\n\nimport jakarta.persistence.AttributeConverter;\nimport jakarta.persistence.Converter;\nimport java.nio.ByteBuffer;\nimport java.nio.charset.StandardCharsets;\nimport java.security.GeneralSecurityException;\nimport java.security.SecureRandom;\nimport java.util.Arrays;\nimport java.util.Base64;\nimport java.util.regex.Matcher;\nimport java.util.regex.Pattern;\nimport javax.crypto.Cipher;\nimport javax.crypto.spec.GCMParameterSpec;\n\n/**\n * Cifra un campo con AES-256-GCM.\n * <p>\n * Formato en la columna: {@code v<N>:Base64( IV de 12 bytes || texto cifrado+tag )}, donde N es la versión\n * de la clave con la que se cifró. Los valores sin prefijo son de la versión 1 y se siguen leyendo.\n * Un IV aleatorio por valor, así el mismo texto no produce el mismo cifrado.\n */\n@Converter\npublic class CampoCifradoConverter implements AttributeConverter<String, String> {\n\n    private static final int LONGITUD_IV = 12;\n    private static final int LONGITUD_TAG_BITS = 128;\n    private static final int VERSION_SIN_PREFIJO = 1;\n    private static final Pattern PREFIJO_VERSION = Pattern.compile(\"^v(\\\\d{1,4}):(.*)$\", Pattern.DOTALL);\n    private static final SecureRandom ALEATORIO = new SecureRandom();\n\n    /** Versión de clave con la que está cifrado un valor de columna. Sin prefijo, la versión 1. */\n    public static int versionDe(String columna) {\n        Matcher prefijo = PREFIJO_VERSION.matcher(columna);\n        return prefijo.matches() ? Integer.parseInt(prefijo.group(1)) : VERSION_SIN_PREFIJO;\n    }\n\n    /** Cifra el texto antes de guardarlo en la base. Los datos personales nunca se guardan en claro. */\n    @Override\n    public String convertToDatabaseColumn(String texto) {\n        if (texto == null) {\n            return null;\n        }\n        int version = ClavesCripto.versionActiva();\n        try {\n            byte[] iv = new byte[LONGITUD_IV];\n            ALEATORIO.nextBytes(iv);\n            Cipher cipher = Cipher.getInstance(\"AES/GCM/NoPadding\");\n            cipher.init(Cipher.ENCRYPT_MODE, ClavesCripto.cifrado(version), new GCMParameterSpec(LONGITUD_TAG_BITS, iv));\n            byte[] cifrado = cipher.doFinal(texto.getBytes(StandardCharsets.UTF_8));\n            byte[] salida = ByteBuffer.allocate(iv.length + cifrado.length).put(iv).put(cifrado).array();\n            return \"v\" + version + \":\" + Base64.getEncoder().encodeToString(salida);\n        } catch (GeneralSecurityException e) {\n            throw new IllegalStateException(\"No se pudo cifrar un campo personal\", e);\n        }\n    }\n\n    /** Descifra el valor leído de la base. Acepta valores sin prefijo de versión. */\n    @Override\n    public String convertToEntityAttribute(String columna) {\n        if (columna == null) {\n            return null;\n        }\n        int version = VERSION_SIN_PREFIJO;\n        String cuerpo = columna;\n        Matcher prefijo = PREFIJO_VERSION.matcher(columna);\n        if (prefijo.matches()) {\n            version = Integer.parseInt(prefijo.group(1));\n            cuerpo = prefijo.group(2);\n        }\n        try {\n            byte[] datos = Base64.getDecoder().decode(cuerpo);\n            byte[] iv = Arrays.copyOfRange(datos, 0, LONGITUD_IV);\n            byte[] cifrado = Arrays.copyOfRange(datos, LONGITUD_IV, datos.length);\n            Cipher cipher = Cipher.getInstance(\"AES/GCM/NoPadding\");\n            cipher.init(Cipher.DECRYPT_MODE, ClavesCripto.cifrado(version), new GCMParameterSpec(LONGITUD_TAG_BITS, iv));\n            return new String(cipher.doFinal(cifrado), StandardCharsets.UTF_8);\n        } catch (GeneralSecurityException e) {\n            throw new IllegalStateException(\"No se pudo descifrar un campo personal\", e);\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/infrastructure/crypto/ClavesCripto.java": "package com.mx.josesaid.develop.clientes.infrastructure.crypto;\n\nimport java.util.Map;\nimport javax.crypto.SecretKey;\nimport javax.crypto.spec.SecretKeySpec;\n\n/**\n * Almacén de las claves de cifrado del proceso. Hay una clave AES por versión; se cifra siempre\n * con la versión activa, y se descifra con la versión que indica el prefijo del valor.\n * Lo llena {@code CryptoConfig} al arrancar, porque los convertidores JPA los crea Hibernate.\n */\npublic final class ClavesCripto {\n\n    private static volatile Map<Integer, SecretKey> cifrados = Map.of();\n    private static volatile int versionActiva = 1;\n    private static volatile SecretKey indice;\n\n    /** Clase de utilidad; no se instancia. */\n    private ClavesCripto() {\n    }\n\n    /** Configura una sola clave de cifrado, como versión 1. Ambas deben tener 32 bytes y ser distintas. */\n    public static void configurar(byte[] claveCifrado, byte[] claveIndice) {\n        configurar(Map.of(1, claveCifrado), 1, claveIndice);\n    }\n\n    /** Configura varias versiones de clave de cifrado y cuál usar para cifrar. */\n    public static void configurar(Map<Integer, byte[]> clavesCifrado, int version, byte[] claveIndice) {\n        Map<Integer, SecretKey> claves = new java.util.HashMap<>();\n        clavesCifrado.forEach((numero, bytes) -> claves.put(numero, new SecretKeySpec(bytes, \"AES\")));\n        if (!claves.containsKey(version)) {\n            throw new IllegalStateException(\"La versión activa de clave \" + version + \" no está configurada\");\n        }\n        cifrados = Map.copyOf(claves);\n        versionActiva = version;\n        indice = new SecretKeySpec(claveIndice, \"HmacSHA256\");\n    }\n\n    /** Devuelve la versión de clave usada para cifrar nuevos valores. */\n    static int versionActiva() {\n        return versionActiva;\n    }\n\n    /** Devuelve la clave AES de una versión. Falla si esa versión no está configurada. */\n    static SecretKey cifrado(int version) {\n        SecretKey clave = cifrados.get(version);\n        if (clave == null) {\n            throw new IllegalStateException(\"Versión de clave de cifrado no configurada: \" + version);\n        }\n        return clave;\n    }\n\n    /** Devuelve la clave del índice de búsqueda. */\n    static SecretKey indice() {\n        return requerida(indice, \"indice\");\n    }\n\n    /** Verifica que la clave requerida esté configurada antes de usarla. */\n    private static SecretKey requerida(SecretKey clave, String nombre) {\n        if (clave == null) {\n            throw new IllegalStateException(\"Clave de \" + nombre + \" no configurada\");\n        }\n        return clave;\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/infrastructure/crypto/IndiceHash.java": "package com.mx.josesaid.develop.clientes.infrastructure.crypto;\n\nimport java.security.GeneralSecurityException;\nimport java.text.Normalizer;\nimport java.util.HexFormat;\nimport java.util.Locale;\nimport javax.crypto.Mac;\n\n/**\n * Índices de búsqueda y de duplicados: HMAC-SHA256 en hexadecimal (64 caracteres).\n * Cada valor se normaliza antes de firmarse y lleva un prefijo por tipo para que dos tipos\n * de dato distintos nunca produzcan el mismo índice.\n */\npublic final class IndiceHash {\n\n    /** Clase de utilidad; no se instancia. */\n    private IndiceHash() {\n    }\n\n    /** RFC en mayúsculas, sin espacios. */\n    public static String rfc(String valor) {\n        return hmac(\"rfc:\" + valor.trim().toUpperCase(Locale.ROOT));\n    }\n\n    /** Correo en minúsculas, sin espacios. */\n    public static String correo(String valor) {\n        return hmac(\"correo:\" + valor.trim().toLowerCase(Locale.ROOT));\n    }\n\n    /** Nombre sin acentos, en minúsculas y con espacios simples. */\n    public static String nombre(String valor) {\n        return hmac(\"nombre:\" + normalizarNombre(valor));\n    }\n\n    /** Normaliza un nombre: sin acentos, en minúsculas y con espacios simples. */\n    static String normalizarNombre(String valor) {\n        String sinAcentos = Normalizer.normalize(valor.trim(), Normalizer.Form.NFD).replaceAll(\"\\\\p{M}\", \"\");\n        return sinAcentos.replaceAll(\"\\\\s+\", \" \").toLowerCase(Locale.ROOT);\n    }\n\n    /** Calcula el HMAC-SHA256 en hexadecimal con la clave del índice. */\n    private static String hmac(String entrada) {\n        try {\n            Mac mac = Mac.getInstance(\"HmacSHA256\");\n            mac.init(ClavesCripto.indice());\n            return HexFormat.of().formatHex(mac.doFinal(entrada.getBytes(java.nio.charset.StandardCharsets.UTF_8)));\n        } catch (GeneralSecurityException e) {\n            throw new IllegalStateException(\"No se pudo calcular el índice de búsqueda\", e);\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/infrastructure/crypto/RecifradorCamposRunner.java": "package com.mx.josesaid.develop.clientes.infrastructure.crypto;\n\nimport java.util.List;\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\nimport org.springframework.boot.ApplicationArguments;\nimport org.springframework.boot.ApplicationRunner;\nimport org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;\nimport org.springframework.stereotype.Component;\n\n/**\n * Re-cifra los campos personales de clientes a la versión activa. Solo corre con\n * {@code CRYPTO_RECIFRADO_ACTIVO=true}; por defecto no toca datos. Registra solo conteos, nunca valores.\n */\n@Component\n@ConditionalOnProperty(name = \"app.crypto.recifrado.activo\", havingValue = \"true\")\npublic class RecifradorCamposRunner implements ApplicationRunner {\n\n    private static final Logger log = LoggerFactory.getLogger(RecifradorCamposRunner.class);\n    private static final int TAMANO_LOTE = 500;\n    /** Columnas personales que se re-cifran, con su tabla. */\n    private static final List<String[]> CAMPOS = List.of(\n            new String[] {\"prospecto\", \"nombre_cifrado\"},\n            new String[] {\"prospecto\", \"correo_cifrado\"},\n            new String[] {\"prospecto\", \"rfc_cifrado\"},\n            new String[] {\"cliente\", \"rfc_cifrado\"},\n            new String[] {\"contacto\", \"nombre_cifrado\"},\n            new String[] {\"contacto\", \"correo_cifrado\"},\n            new String[] {\"interaccion\", \"resumen_cifrado\"});\n\n    private final RecifradorJdbc almacen;\n    private final CampoCifradoConverter convertidor = new CampoCifradoConverter();\n\n    /** Recibe el acceso JDBC a las columnas. */\n    public RecifradorCamposRunner(RecifradorJdbc almacen) {\n        this.almacen = almacen;\n    }\n\n    /** Al arrancar, re-cifra todas las columnas de la lista a la versión activa. Solo registra conteos, nunca valores. */\n    @Override\n    public void run(ApplicationArguments args) {\n        RecifradorPorLotes recifrador = new RecifradorPorLotes(almacen, TAMANO_LOTE,\n                valor -> convertidor.convertToDatabaseColumn(convertidor.convertToEntityAttribute(valor)));\n        for (String[] campo : CAMPOS) {\n            int total = recifrador.ejecutar(campo[0], campo[1]);\n            log.info(\"Campos re-cifrados en {}.{}: {}\", campo[0], campo[1], total);\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/infrastructure/crypto/RecifradorJdbc.java": "package com.mx.josesaid.develop.clientes.infrastructure.crypto;\n\nimport java.util.List;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.springframework.stereotype.Component;\n\n/**\n * Implementación JDBC de {@link RecifradorPorLotes.Almacen}. Tabla y columna vienen de constantes del código\n * (nunca de entrada del usuario), así que se componen en el SQL; los valores van como parámetros.\n */\n@Component\npublic class RecifradorJdbc implements RecifradorPorLotes.Almacen {\n\n    private final JdbcTemplate jdbc;\n\n    /** Acceso JDBC para el re-cifrado por lotes. */\n    public RecifradorJdbc(JdbcTemplate jdbc) {\n        this.jdbc = jdbc;\n    }\n\n    /** Devuelve hasta el límite de filas cuyo valor aún no está en la versión activa. */\n    @Override\n    public List<RecifradorPorLotes.Fila> pendientes(String tabla, String columna, int limite) {\n        String sql = \"SELECT id, \" + columna + \" AS valor FROM \" + tabla\n                + \" WHERE \" + columna + \" IS NOT NULL AND \" + columna + \" NOT LIKE ? ORDER BY id LIMIT ?\";\n        return jdbc.query(sql,\n                (resultado, fila) -> new RecifradorPorLotes.Fila(resultado.getObject(\"id\"), resultado.getString(\"valor\")),\n                \"v\" + ClavesCripto.versionActiva() + \":%\",\n                limite);\n    }\n\n    /** Cambia el valor de una fila solo si aún vale lo que se leyó. */\n    @Override\n    public boolean actualizar(String tabla, String columna, Object id, String valorAnterior, String valorNuevo) {\n        String sql = \"UPDATE \" + tabla + \" SET \" + columna + \" = ? WHERE id = ? AND \" + columna + \" = ?\";\n        return jdbc.update(sql, valorNuevo, id, valorAnterior) == 1;\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/infrastructure/crypto/RecifradorPorLotes.java": "package com.mx.josesaid.develop.clientes.infrastructure.crypto;\n\nimport java.util.List;\nimport java.util.function.UnaryOperator;\n\n/**\n * Vuelve a cifrar, por lotes, los valores de una columna que no están en la versión activa de la clave.\n * <p>\n * Es reanudable: solo pide filas pendientes, así que si el proceso se corta, al volver a correrlo continúa\n * donde quedó. Cada fila se actualiza solo si su valor sigue siendo el que se leyó, para no pisar una escritura\n * concurrente de la aplicación.\n */\npublic final class RecifradorPorLotes {\n\n    /**\n     * Fila pendiente: su id y el valor cifrado tal como está en la base.\n     *\n     * @param id identificador único del registro, de tipo {@code Object}.\n     * @param valor valor registrado, de tipo {@code String}.\n     */\n    public record Fila(Object id, String valor) {\n    }\n\n    /** Acceso a la base; la implementación JDBC vive aparte para poder probar la lógica sin base de datos. */\n    public interface Almacen {\n\n        /** Hasta {@code limite} filas con valor no nulo que no están en la versión activa. */\n        List<Fila> pendientes(String tabla, String columna, int limite);\n\n        /** Cambia el valor solo si la columna aún vale {@code valorAnterior}. Devuelve si se cambió. */\n        boolean actualizar(String tabla, String columna, Object id, String valorAnterior, String valorNuevo);\n    }\n\n    private final Almacen almacen;\n    private final int tamanoLote;\n    private final UnaryOperator<String> recifrar;\n\n    /** Recibe el acceso a la base, el tamaño de lote y la función que re-cifra un valor. */\n    public RecifradorPorLotes(Almacen almacen, int tamanoLote, UnaryOperator<String> recifrar) {\n        if (tamanoLote < 1) {\n            throw new IllegalArgumentException(\"El tamaño de lote debe ser al menos 1\");\n        }\n        this.almacen = almacen;\n        this.tamanoLote = tamanoLote;\n        this.recifrar = recifrar;\n    }\n\n    /** Recorre la columna hasta que no queden filas pendientes. Devuelve cuántas se re-cifraron. */\n    public int ejecutar(String tabla, String columna) {\n        int recifradas = 0;\n        while (true) {\n            List<Fila> lote = almacen.pendientes(tabla, columna, tamanoLote);\n            if (lote.isEmpty()) {\n                return recifradas;\n            }\n            for (Fila fila : lote) {\n                String nuevo = recifrar.apply(fila.valor());\n                if (!almacen.actualizar(tabla, columna, fila.id(), fila.valor(), nuevo)) {\n                    throw new IllegalStateException(\n                            \"No se actualizó \" + tabla + \".\" + columna + \" para el id \" + fila.id()\n                                    + \": el valor cambió durante el proceso. Vuelva a ejecutar.\");\n                }\n                recifradas++;\n            }\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/infrastructure/indicadores/PublicadorIndicadoresClientes.java": "package com.mx.josesaid.develop.clientes.infrastructure.indicadores;\n\nimport java.math.BigDecimal;\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.time.YearMonth;\nimport java.time.ZoneId;\nimport java.util.concurrent.TimeUnit;\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\nimport org.springframework.beans.factory.annotation.Value;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.springframework.kafka.core.KafkaTemplate;\nimport org.springframework.scheduling.annotation.Scheduled;\nimport org.springframework.stereotype.Component;\nimport tools.jackson.databind.ObjectMapper;\n\n/**\n * Publica a reportes-ejecutivos-ms el indicador \"clientes nuevos del mes\" del área de ventas.\n *\n * <p>Cuenta los clientes dados de alta en el mes (fecha de alta, hora de la Ciudad de México), sin importar\n * su estatus posterior. Se recalculan el mes actual y el anterior en cada ciclo. Es una foto del periodo,\n * no un evento: no pasa por el outbox; si un envío falla, el siguiente ciclo lo corrige.\n */\n@Component\npublic class PublicadorIndicadoresClientes {\n\n    private static final Logger log = LoggerFactory.getLogger(PublicadorIndicadoresClientes.class);\n\n    /** Valor del enum Area de reportes-ejecutivos-ms. */\n    public static final String AREA = \"VENTAS_ATENCION_CLIENTES\";\n    public static final String NOMBRE = \"clientes_nuevos_mes\";\n\n    private static final ZoneId ZONA = ZoneId.of(\"America/Mexico_City\");\n\n    private static final String SQL_ALTAS = \"\"\"\n            SELECT COUNT(*)::numeric\n            FROM cliente\n            WHERE TO_CHAR(fecha_alta, 'YYYY-MM') = ?\n            \"\"\";\n\n    private final JdbcTemplate jdbc;\n    private final KafkaTemplate<String, String> kafka;\n    private final ObjectMapper mapper;\n    private final Clock reloj;\n    private final String topico;\n\n    /** Recibe JDBC para contar, Kafka para publicar, el serializador, el reloj y el tópico. */\n    public PublicadorIndicadoresClientes(JdbcTemplate jdbc, KafkaTemplate<String, String> kafka,\n                                         ObjectMapper mapper, Clock reloj,\n                                         @Value(\"${indicadores.topico:indicadores-areas}\") String topico) {\n        this.jdbc = jdbc;\n        this.kafka = kafka;\n        this.mapper = mapper;\n        this.reloj = reloj;\n        this.topico = topico;\n    }\n\n    /** Publica los indicadores del mes anterior y del mes actual. */\n    @Scheduled(fixedDelayString = \"${indicadores.intervalo-ms:3600000}\",\n            initialDelayString = \"${indicadores.inicio-ms:30000}\")\n    public void publicar() {\n        YearMonth actual = YearMonth.now(reloj.withZone(ZONA));\n        publicarPeriodo(actual.minusMonths(1).toString());\n        publicarPeriodo(actual.toString());\n    }\n\n    /** Calcula y envía el indicador de un mes (\"AAAA-MM\"). Un fallo se registra y se reintenta en el siguiente ciclo. */\n    public void publicarPeriodo(String periodo) {\n        BigDecimal valor = jdbc.queryForObject(SQL_ALTAS, BigDecimal.class, periodo);\n        String payload = mapper.writeValueAsString(\n                new IndicadorEvento(AREA, NOMBRE, periodo, valor, Instant.now(reloj)));\n        try {\n            kafka.send(topico, AREA + \"|\" + NOMBRE + \"|\" + periodo, payload).get(10, TimeUnit.SECONDS);\n            log.info(\"Indicador publicado: {} {} {}\", AREA, NOMBRE, periodo);\n        } catch (InterruptedException ie) {\n            Thread.currentThread().interrupt();\n        } catch (Exception ex) {\n            log.warn(\"No se pudo publicar el indicador {} {}: {}\", NOMBRE, periodo, ex.getClass().getSimpleName());\n        }\n    }\n\n    /**\n     * Formato que espera reportes-ejecutivos-ms (ListenerIndicadores.IndicadorEvento).\n     *\n     * @param area área de negocio a la que pertenece, de tipo {@code String}.\n     * @param nombre nombre descriptivo, de tipo {@code String}.\n     * @param periodo periodo de referencia (por ejemplo, año y mes), de tipo {@code String}.\n     * @param valor valor registrado, de tipo {@code BigDecimal}.\n     * @param fuenteActualizadaUtc fecha y hora (UTC) de la última actualización de la fuente, de tipo {@code Instant}.\n     */\n    public record IndicadorEvento(String area, String nombre, String periodo, BigDecimal valor,\n                                  Instant fuenteActualizadaUtc) {\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/infrastructure/outbox/OutboxEvento.java": "package com.mx.josesaid.develop.clientes.infrastructure.outbox;\n\nimport jakarta.persistence.Column;\nimport jakarta.persistence.Entity;\nimport jakarta.persistence.Id;\nimport jakarta.persistence.Table;\nimport java.time.Instant;\nimport java.util.UUID;\n\n/** Evento pendiente de publicar. Se escribe en la misma transacción que el cambio de estado. */\n@Entity\n@Table(name = \"outbox_evento\")\npublic class OutboxEvento {\n\n    @Id\n    private UUID id;\n\n    @Column(name = \"tipo_agregado\", nullable = false, length = 50)\n    private String tipoAgregado;\n\n    @Column(name = \"agregado_id\", nullable = false)\n    private UUID agregadoId;\n\n    @Column(name = \"tipo_evento\", nullable = false, length = 80)\n    private String tipoEvento;\n\n    @Column(name = \"payload\", nullable = false)\n    private String payload;\n\n    @Column(name = \"created_at\", nullable = false)\n    private Instant createdAt;\n\n    @Column(name = \"enviado_at\")\n    private Instant enviadoAt;\n\n    /** Constructor exigido por JPA. No se usa en el código de la aplicación. */\n    protected OutboxEvento() {\n    }\n\n    /** Crea un evento pendiente de publicar en el outbox. */\n    public OutboxEvento(UUID id, String tipoAgregado, UUID agregadoId, String tipoEvento, String payload, Instant createdAt) {\n        this.id = id;\n        this.tipoAgregado = tipoAgregado;\n        this.agregadoId = agregadoId;\n        this.tipoEvento = tipoEvento;\n        this.payload = payload;\n        this.createdAt = createdAt;\n    }\n\n    /** Marca el evento como enviado en la fecha indicada. */\n    public void marcarEnviado(Instant ahora) {\n        this.enviadoAt = ahora;\n    }\n\n    /** Devuelve el identificador del evento. */\n    public UUID getId() {\n        return id;\n    }\n\n    /** Devuelve el id del agregado al que pertenece el evento. */\n    public UUID getAgregadoId() {\n        return agregadoId;\n    }\n\n    /** Devuelve el tipo del evento. */\n    public String getTipoEvento() {\n        return tipoEvento;\n    }\n\n    /** Devuelve el contenido JSON del evento. */\n    public String getPayload() {\n        return payload;\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/infrastructure/outbox/OutboxPublicador.java": "package com.mx.josesaid.develop.clientes.infrastructure.outbox;\n\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.util.concurrent.ExecutionException;\nimport java.util.concurrent.TimeUnit;\nimport java.util.concurrent.TimeoutException;\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\nimport org.springframework.beans.factory.annotation.Value;\nimport org.springframework.kafka.core.KafkaTemplate;\nimport org.springframework.scheduling.annotation.Scheduled;\nimport org.springframework.stereotype.Component;\nimport org.springframework.transaction.annotation.Transactional;\n\n/**\n * Publica los eventos pendientes hacia Kafka. Garantía: al menos una vez.\n * Se detiene en el primer fallo del lote para conservar el orden; el resto se reintenta en el siguiente ciclo.\n */\n@Component\npublic class OutboxPublicador {\n\n    private static final Logger LOG = LoggerFactory.getLogger(OutboxPublicador.class);\n    private static final long ESPERA_ENVIO_SEGUNDOS = 5;\n\n    private final OutboxRepository repositorio;\n    private final KafkaTemplate<String, String> kafka;\n    private final String topico;\n    private final Clock reloj;\n\n    /** Recibe el repositorio del outbox, el productor de Kafka y el reloj. */\n    public OutboxPublicador(OutboxRepository repositorio,\n                            KafkaTemplate<String, String> kafka,\n                            @Value(\"${app.eventos.topico}\") String topico,\n                            Clock reloj) {\n        this.repositorio = repositorio;\n        this.kafka = kafka;\n        this.topico = topico;\n        this.reloj = reloj;\n    }\n\n    /** Envía a Kafka los eventos pendientes. Si un envío falla, el evento queda para el siguiente ciclo. */\n    @Scheduled(fixedDelayString = \"${app.eventos.intervalo-publicacion-ms}\")\n    @Transactional\n    public void publicarPendientes() {\n        for (OutboxEvento evento : repositorio.findTop100ByEnviadoAtIsNullOrderByCreatedAtAsc()) {\n            try {\n                kafka.send(topico, evento.getAgregadoId().toString(), evento.getPayload())\n                        .get(ESPERA_ENVIO_SEGUNDOS, TimeUnit.SECONDS);\n                evento.marcarEnviado(Instant.now(reloj));\n            } catch (InterruptedException e) {\n                Thread.currentThread().interrupt();\n                LOG.warn(\"Publicación interrumpida; se reintenta en el siguiente ciclo\");\n                return;\n            } catch (ExecutionException | TimeoutException e) {\n                LOG.warn(\"Evento pendiente de publicar, se reintenta. eventoId={} tipo={}\",\n                        evento.getId(), evento.getTipoEvento());\n                return;\n            }\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/infrastructure/outbox/OutboxRepository.java": "package com.mx.josesaid.develop.clientes.infrastructure.outbox;\n\nimport java.util.List;\nimport java.util.UUID;\nimport org.springframework.data.jpa.repository.JpaRepository;\n\n/** Acceso a la tabla del outbox con Spring Data JPA. */\npublic interface OutboxRepository extends JpaRepository<OutboxEvento, UUID> {\n\n    List<OutboxEvento> findTop100ByEnviadoAtIsNullOrderByCreatedAtAsc();\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/infrastructure/persistence/ClienteRepository.java": "package com.mx.josesaid.develop.clientes.infrastructure.persistence;\n\nimport com.mx.josesaid.develop.clientes.domain.Cliente;\nimport com.mx.josesaid.develop.clientes.domain.EstatusCliente;\nimport java.util.List;\nimport java.util.Optional;\nimport java.util.UUID;\nimport org.springframework.data.domain.Page;\nimport org.springframework.data.domain.Pageable;\nimport org.springframework.data.jpa.repository.JpaRepository;\n\n/** Acceso a la tabla de clientes con Spring Data JPA. */\npublic interface ClienteRepository extends JpaRepository<Cliente, UUID> {\n\n    Optional<Cliente> findFirstByRfcHashAndEstatusNot(String rfcHash, EstatusCliente estatus);\n\n    Optional<Cliente> findFirstByProspectoId(UUID prospectoId);\n\n    Page<Cliente> findByRfcHash(String rfcHash, Pageable pageable);\n\n    Page<Cliente> findByRazonSocialContainingIgnoreCase(String fragmento, Pageable pageable);\n\n    List<Cliente> findByRazonSocialIgnoreCase(String razonSocial);\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/infrastructure/persistence/ConsentimientoRepository.java": "package com.mx.josesaid.develop.clientes.infrastructure.persistence;\n\nimport com.mx.josesaid.develop.clientes.domain.Consentimiento;\nimport java.util.UUID;\nimport org.springframework.data.jpa.repository.JpaRepository;\n\n/** Acceso a la tabla de consentimientos con Spring Data JPA. */\npublic interface ConsentimientoRepository extends JpaRepository<Consentimiento, UUID> {\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/infrastructure/persistence/ContactoRepository.java": "package com.mx.josesaid.develop.clientes.infrastructure.persistence;\n\nimport com.mx.josesaid.develop.clientes.domain.Contacto;\nimport java.util.List;\nimport java.util.Optional;\nimport java.util.UUID;\nimport org.springframework.data.jpa.repository.JpaRepository;\n\n/** Acceso a la tabla de contactos con Spring Data JPA. */\npublic interface ContactoRepository extends JpaRepository<Contacto, UUID> {\n\n    List<Contacto> findByCorreoHash(String correoHash);\n\n    Optional<Contacto> findFirstByClienteIdAndPrincipalTrue(UUID clienteId);\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/infrastructure/persistence/InteraccionRepository.java": "package com.mx.josesaid.develop.clientes.infrastructure.persistence;\n\nimport com.mx.josesaid.develop.clientes.domain.Interaccion;\nimport java.util.Optional;\nimport java.util.UUID;\nimport org.springframework.data.domain.Page;\nimport org.springframework.data.domain.Pageable;\nimport org.springframework.data.jpa.repository.JpaRepository;\n\n/** Acceso a la tabla de interacciones con Spring Data JPA. */\npublic interface InteraccionRepository extends JpaRepository<Interaccion, UUID> {\n\n    Page<Interaccion> findByClienteId(UUID clienteId, Pageable pageable);\n\n    Optional<Interaccion> findFirstByClienteIdOrderByFechaDesc(UUID clienteId);\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/infrastructure/persistence/ProspectoRepository.java": "package com.mx.josesaid.develop.clientes.infrastructure.persistence;\n\nimport com.mx.josesaid.develop.clientes.domain.EstatusProspecto;\nimport com.mx.josesaid.develop.clientes.domain.Prospecto;\nimport java.time.Instant;\nimport java.util.List;\nimport java.util.UUID;\nimport org.springframework.data.jpa.repository.JpaRepository;\n\n/** Acceso a la tabla de prospectos con Spring Data JPA. */\npublic interface ProspectoRepository extends JpaRepository<Prospecto, UUID> {\n\n    List<Prospecto> findByCorreoHash(String correoHash);\n\n    List<Prospecto> findByNombreHash(String nombreHash);\n\n    /** Cuenta los prospectos convertidos en un rango de fechas. */\n    long countByEstatusAndFechaConversionGreaterThanEqualAndFechaConversionLessThan(\n            EstatusProspecto estatus, Instant desde, Instant hasta);\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/seguridad/EntradaNoAutorizada.java": "package com.mx.josesaid.develop.clientes.seguridad;\n\nimport jakarta.servlet.http.HttpServletRequest;\nimport jakarta.servlet.http.HttpServletResponse;\nimport java.io.IOException;\nimport org.springframework.security.core.AuthenticationException;\nimport org.springframework.security.oauth2.jwt.JwtValidationException;\nimport org.springframework.security.web.AuthenticationEntryPoint;\n\n/**\n * Responde 401 y deja el motivo en WWW-Authenticate. Solo expone el motivo de sesión cerrada;\n * cualquier otro fallo de validación se reporta como \"Invalid token\", sin detalles de decodificación.\n * Spring puede llamar dos veces al punto de entrada en la misma petición: el primer motivo se conserva.\n */\npublic class EntradaNoAutorizada implements AuthenticationEntryPoint {\n\n    private static final String MOTIVO_GENERICO = \"Invalid token\";\n    private static final String ATRIBUTO = EntradaNoAutorizada.class.getName() + \".motivo\";\n\n    /** Responde 401 cuando la petición no trae un token válido o el token fue rechazado. */\n    @Override\n    public void commence(HttpServletRequest request, HttpServletResponse response, AuthenticationException ex)\n            throws IOException {\n        String previo = (String) request.getAttribute(ATRIBUTO);\n        String motivo = previo != null ? previo : motivo(ex);\n        request.setAttribute(ATRIBUTO, motivo);\n        response.setHeader(\"WWW-Authenticate\",\n                \"Bearer error=\\\"invalid_token\\\", error_description=\\\"\" + motivo + \"\\\"\");\n        response.sendError(HttpServletResponse.SC_UNAUTHORIZED);\n    }\n\n    /** Explica por qué se rechazó el token, en texto breve para el log. */\n    private static String motivo(Throwable ex) {\n        for (Throwable t = ex; t != null; t = t.getCause()) {\n            if (t instanceof JwtValidationException jve && jve.getErrors().stream()\n                    .anyMatch(e -> ValidadorRevocacion.MOTIVO.equals(e.getDescription()))) {\n                return ValidadorRevocacion.MOTIVO;\n            }\n        }\n        return MOTIVO_GENERICO;\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/seguridad/ListenerRevocaciones.java": "package com.mx.josesaid.develop.clientes.seguridad;\n\nimport java.time.Instant;\nimport java.util.Map;\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\nimport org.springframework.kafka.annotation.KafkaListener;\nimport org.springframework.stereotype.Component;\nimport tools.jackson.databind.ObjectMapper;\n\n/**\n * Recibe de usuarios-accesos-ms los cierres de sesión y los aplica a la copia local de revocaciones.\n * Los eventos ajenos se ignoran; un mensaje inválido se registra y se descarta.\n * Cada arranque usa un grupo de consumo nuevo y lee el topic desde el inicio: así reconstruye las\n * revocaciones vigentes. Los eventos vencidos los descarta RevocacionSesiones.\n */\n@Component\npublic class ListenerRevocaciones {\n\n    private static final Logger log = LoggerFactory.getLogger(ListenerRevocaciones.class);\n\n    private final RevocacionSesiones revocaciones;\n    private final ObjectMapper mapper;\n\n    /** Recibe la copia local de revocaciones y el lector JSON. */\n    public ListenerRevocaciones(RevocacionSesiones revocaciones, ObjectMapper mapper) {\n        this.revocaciones = revocaciones;\n        this.mapper = mapper;\n    }\n\n    /** Aplica al instante un evento de cierre de sesión recibido por Kafka. */\n    @KafkaListener(topics = \"${seguridad.revocaciones.topico:usuarios-accesos.eventos}\",\n                   groupId = \"clientes-ms-revocaciones-#{T(java.util.UUID).randomUUID()}\",\n                   properties = \"auto.offset.reset=earliest\")\n    public void recibir(String mensaje) {\n        try {\n            Sobre sobre = mapper.readValue(mensaje, Sobre.class);\n            String tipo = sobre.tipo();\n            if (!\"sesion-cerrada\".equals(tipo) && !\"sesiones-usuario-cerradas\".equals(tipo)) {\n                return;\n            }\n            Map<String, Object> datos = sobre.datos() == null ? Map.of() : sobre.datos();\n            Instant ocurridoEn = Instant.parse(String.valueOf(datos.get(\"ocurridoEn\")));\n            if (\"sesion-cerrada\".equals(tipo)) {\n                revocaciones.revocarSesion(String.valueOf(datos.get(\"sid\")), ocurridoEn);\n            } else {\n                revocaciones.revocarUsuario(String.valueOf(datos.get(\"usuarioId\")), ocurridoEn);\n            }\n        } catch (RuntimeException e) {\n            log.warn(\"Evento de revocación descartado: {}\", e.getClass().getSimpleName());\n        }\n    }\n\n    /**\n     * Sobre que publica usuarios-accesos-ms por el outbox.\n     *\n     * @param tipo tipo o clasificación del registro, de tipo {@code String}.\n     * @param agregadoId identificador del agregado de dominio al que pertenece el evento, de tipo {@code String}.\n     * @param datos datos específicos de la operación, de tipo {@code Map<String, Object>}.\n     */\n    public record Sobre(String tipo, String agregadoId, Map<String, Object> datos) {\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/seguridad/RevocacionSesiones.java": "package com.mx.josesaid.develop.clientes.seguridad;\n\nimport java.time.Duration;\nimport java.time.Instant;\nimport java.util.Map;\nimport java.util.concurrent.ConcurrentHashMap;\nimport org.springframework.stereotype.Component;\n\n/**\n * Sesiones cerradas, recordadas en memoria solo mientras pueda haber tokens vigentes.\n * Cada servicio mantiene su copia: un reinicio la vacía, y los tokens revocados expiran igual en 15 minutos.\n */\n@Component\npublic class RevocacionSesiones {\n\n    /** Vida del access token (15 min) más un margen. Pasado ese tiempo, ningún token revocado sigue vigente. */\n    public static final Duration VIDA = Duration.ofMinutes(20);\n\n    private final Map<String, Instant> sesiones = new ConcurrentHashMap<>();\n    private final Map<String, Instant> usuarios = new ConcurrentHashMap<>();\n\n    /** Revoca una sesión (su sid) cerrada en el instante dado. */\n    public void revocarSesion(String sid, Instant ocurridoEn) {\n        if (sid == null || vencido(ocurridoEn)) {\n            return;\n        }\n        sesiones.put(sid, ocurridoEn);\n    }\n\n    /** Revoca los tokens del usuario emitidos antes del instante dado. */\n    public void revocarUsuario(String usuarioId, Instant ocurridoEn) {\n        if (usuarioId == null || vencido(ocurridoEn)) {\n            return;\n        }\n        usuarios.merge(usuarioId, ocurridoEn, (actual, nuevoValor) -> nuevoValor.isAfter(actual) ? nuevoValor : actual);\n    }\n\n    /** true si un token con ese sid, usuario y fecha de emisión ya no debe aceptarse. */\n    public boolean revocado(String sid, String usuarioId, Instant emitidoEn) {\n        limpiar();\n        if (sid != null && sesiones.containsKey(sid)) {\n            return true;\n        }\n        Instant cerradoEn = usuarioId == null ? null : usuarios.get(usuarioId);\n        return cerradoEn != null && emitidoEn != null && emitidoEn.isBefore(cerradoEn);\n    }\n\n    /** Indica si un registro de revocación ya venció y puede descartarse. */\n    private static boolean vencido(Instant ocurridoEn) {\n        return ocurridoEn == null || ocurridoEn.plus(VIDA).isBefore(Instant.now());\n    }\n\n    /** Elimina las revocaciones vencidas para no crecer sin límite. */\n    private void limpiar() {\n        Instant limite = Instant.now().minus(VIDA);\n        sesiones.values().removeIf(t -> t.isBefore(limite));\n        usuarios.values().removeIf(t -> t.isBefore(limite));\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/clientes/seguridad/ValidadorRevocacion.java": "package com.mx.josesaid.develop.clientes.seguridad;\n\nimport org.springframework.security.oauth2.core.OAuth2Error;\nimport org.springframework.security.oauth2.core.OAuth2TokenValidator;\nimport org.springframework.security.oauth2.core.OAuth2TokenValidatorResult;\nimport org.springframework.security.oauth2.jwt.Jwt;\n\n/** Rechaza los tokens de sesiones cerradas. Se combina con la validación estándar de firma y vencimiento. */\npublic class ValidadorRevocacion implements OAuth2TokenValidator<Jwt> {\n\n    /** Motivo que se devuelve al cliente cuando la sesión fue cerrada. */\n    public static final String MOTIVO = \"La sesion fue cerrada\";\n\n    private static final OAuth2Error REVOCADO = new OAuth2Error(\"invalid_token\", MOTIVO, null);\n\n    private final RevocacionSesiones revocaciones;\n\n    /** Recibe la copia local de revocaciones. */\n    public ValidadorRevocacion(RevocacionSesiones revocaciones) {\n        this.revocaciones = revocaciones;\n    }\n\n    /** Rechaza el JWT si su sesión o su usuario fueron revocados, aunque la firma y el vencimiento sean válidos. */\n    @Override\n    public OAuth2TokenValidatorResult validate(Jwt jwt) {\n        boolean revocado = revocaciones.revocado(jwt.getClaimAsString(\"sid\"), jwt.getSubject(), jwt.getIssuedAt());\n        return revocado ? OAuth2TokenValidatorResult.failure(REVOCADO) : OAuth2TokenValidatorResult.success();\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/clientes/api/ClienteControllerAutorizacionTest.java": "package com.mx.josesaid.develop.clientes.api;\n\nimport static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.jwt;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.patch;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;\nimport static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;\n\nimport com.mx.josesaid.develop.clientes.application.Auditoria;\nimport com.mx.josesaid.develop.clientes.application.ClienteService;\nimport com.mx.josesaid.develop.clientes.config.SeguridadConfig;\nimport com.mx.josesaid.develop.clientes.seguridad.RevocacionSesiones;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.http.MediaType;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.boot.test.context.TestConfiguration;\nimport org.springframework.boot.webmvc.test.autoconfigure.WebMvcTest;\nimport org.springframework.context.annotation.Import;\nimport org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;\nimport org.springframework.security.core.authority.SimpleGrantedAuthority;\nimport org.springframework.test.context.bean.override.mockito.MockitoBean;\nimport org.springframework.test.web.servlet.MockMvc;\nimport org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder;\n\n/**\n * Matriz de autorización de ClienteController (endpoints de lectura).\n * Un rol permitido no debe recibir 401 ni 403. Un rol no permitido debe recibir 403.\n * Los servicios están simulados: estas pruebas solo miden la autorización.\n */\n@WebMvcTest(ClienteController.class)\n@Import({SeguridadConfig.class, ClienteControllerAutorizacionTest.Configuracion.class})\nclass ClienteControllerAutorizacionTest {\n\n    private static final String SUJETO = \"6f1c2e7a-9a3b-4c1d-8e2f-1a2b3c4d5e6f\";\n    private static final String ID = \"11111111-2222-3333-4444-555555555555\";\n    private static final String NUEVO_CLIENTE = \"{\\\"razonSocial\\\":\\\"Acme SA\\\",\\\"rfc\\\":\\\"AAA010101AAA\\\",\"\n            + \"\\\"contactoPrincipal\\\":{\\\"nombre\\\":\\\"Ana\\\",\\\"correo\\\":\\\"ana@ejemplo.com\\\",\\\"rol\\\":\\\"COMPRAS\\\"}}\";\n    private static final String ACTUALIZAR = \"{\\\"razonSocial\\\":\\\"Acme SA de CV\\\"}\";\n    private static final String ESTATUS = \"{\\\"estatus\\\":\\\"ACTIVO\\\"}\";\n    private static final String CONTACTO = \"{\\\"nombre\\\":\\\"Luis\\\",\\\"correo\\\":\\\"luis@ejemplo.com\\\",\\\"rol\\\":\\\"COMPRAS\\\",\\\"principal\\\":false}\";\n\n    @TestConfiguration\n    @EnableWebSecurity\n    static class Configuracion {\n    }\n\n    @Autowired\n    private MockMvc mvc;\n\n    @MockitoBean\n    private ClienteService servicio;\n\n    @MockitoBean\n    private Auditoria auditoria;\n\n    @MockitoBean\n    private Presentacion presentacion;\n\n    @MockitoBean\n    private RevocacionSesiones revocaciones;\n\n    private MockHttpServletRequestBuilder lectura(String ruta, String... roles) {\n        java.util.List<org.springframework.security.core.GrantedAuthority> autoridades = java.util.Arrays.stream(roles)\n                .<org.springframework.security.core.GrantedAuthority>map(r -> new SimpleGrantedAuthority(\"ROLE_\" + r))\n                .toList();\n        return get(ruta).with(jwt().jwt(j -> j.subject(SUJETO)).authorities(autoridades));\n    }\n\n    private void permitido(String ruta, String rol) throws Exception {\n        int codigo;\n        try {\n            codigo = mvc.perform(lectura(ruta, rol)).andReturn().getResponse().getStatus();\n        } catch (jakarta.servlet.ServletException e) {\n            // El servicio simulado devuelve null y el controlador falla después de la autorización:\n            // llegar hasta el controlador significa que el rol fue aceptado.\n            codigo = 200;\n        }\n        org.assertj.core.api.Assertions.assertThat(codigo)\n                .as(\"%s debería estar permitido para %s\", ruta, rol)\n                .isNotIn(401, 403);\n    }\n\n    private void denegado(String ruta, String rol) throws Exception {\n        mvc.perform(lectura(ruta, rol)).andExpect(status().isForbidden());\n    }\n\n    @Test\n    void listarClientes() throws Exception {\n        permitido(\"/v1/clientes\", \"ADMIN\");\n        permitido(\"/v1/clientes\", \"VENTAS\");\n        denegado(\"/v1/clientes\", \"LEGAL\");\n        denegado(\"/v1/clientes\", \"COMPRAS\");\n    }\n\n    @Test\n    void obtenerCliente() throws Exception {\n        permitido(\"/v1/clientes/\" + ID, \"ADMIN\");\n        permitido(\"/v1/clientes/\" + ID, \"VENTAS\");\n        denegado(\"/v1/clientes/\" + ID, \"LEGAL\");\n    }\n\n    @Test\n    void sinRolNoHayAcceso() throws Exception {\n        denegado(\"/v1/clientes\", \"\");\n    }\n\n    private void escribe(MockHttpServletRequestBuilder req, String ruta, String rol, String cuerpo, boolean permite)\n            throws Exception {\n        MockHttpServletRequestBuilder conRol = req.contentType(MediaType.APPLICATION_JSON).content(cuerpo)\n                .with(jwt().jwt(j -> j.subject(SUJETO))\n                        .authorities(rol.isEmpty() ? java.util.List.of()\n                                : java.util.List.of(new SimpleGrantedAuthority(\"ROLE_\" + rol))));\n        if (permite) {\n            permitido(conRol, ruta, rol);\n        } else {\n            mvc.perform(conRol).andExpect(status().isForbidden());\n        }\n    }\n\n    private void permitido(MockHttpServletRequestBuilder req, String ruta, String rol) throws Exception {\n        int codigo;\n        try {\n            codigo = mvc.perform(req).andReturn().getResponse().getStatus();\n        } catch (jakarta.servlet.ServletException e) {\n            codigo = 200; // llegó al controlador: el rol fue aceptado\n        }\n        org.assertj.core.api.Assertions.assertThat(codigo)\n                .as(\"%s debería estar permitido para %s\", ruta, rol)\n                .isNotIn(401, 403);\n    }\n\n    @Test\n    void crearCliente() throws Exception {\n        String ruta = \"/v1/clientes\";\n        escribe(post(ruta), ruta, \"ADMIN\", NUEVO_CLIENTE, true);\n        escribe(post(ruta), ruta, \"VENTAS\", NUEVO_CLIENTE, false);\n        escribe(post(ruta), ruta, \"LEGAL\", NUEVO_CLIENTE, false);\n    }\n\n    @Test\n    void actualizarCliente() throws Exception {\n        String ruta = \"/v1/clientes/\" + ID;\n        escribe(patch(ruta), ruta, \"ADMIN\", ACTUALIZAR, true);\n        escribe(patch(ruta), ruta, \"VENTAS\", ACTUALIZAR, false);\n        escribe(patch(ruta), ruta, \"COMPRAS\", ACTUALIZAR, false);\n    }\n\n    @Test\n    void cambiarEstatusCliente() throws Exception {\n        String ruta = \"/v1/clientes/\" + ID + \"/estatus\";\n        escribe(patch(ruta), ruta, \"ADMIN\", ESTATUS, true);\n        escribe(patch(ruta), ruta, \"VENTAS\", ESTATUS, false);\n        escribe(patch(ruta), ruta, \"LEGAL\", ESTATUS, false);\n    }\n\n    @Test\n    void agregarContacto() throws Exception {\n        String ruta = \"/v1/clientes/\" + ID + \"/contactos\";\n        escribe(post(ruta), ruta, \"ADMIN\", CONTACTO, true);\n        escribe(post(ruta), ruta, \"VENTAS\", CONTACTO, false);\n        escribe(post(ruta), ruta, \"COMPRAS\", CONTACTO, false);\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/clientes/api/ClienteControllerValidacionTest.java": "package com.mx.josesaid.develop.clientes.api;\n\nimport static org.mockito.ArgumentMatchers.any;\nimport static org.mockito.Mockito.when;\nimport static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.jwt;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;\nimport static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;\n\nimport com.mx.josesaid.develop.clientes.application.Auditoria;\nimport com.mx.josesaid.develop.clientes.application.ClienteService;\nimport com.mx.josesaid.develop.clientes.config.SeguridadConfig;\nimport com.mx.josesaid.develop.clientes.seguridad.RevocacionSesiones;\nimport java.util.List;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.boot.test.context.TestConfiguration;\nimport org.springframework.boot.webmvc.test.autoconfigure.WebMvcTest;\nimport org.springframework.context.annotation.Import;\nimport org.springframework.data.domain.PageImpl;\nimport org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;\nimport org.springframework.security.core.authority.SimpleGrantedAuthority;\nimport org.springframework.test.context.bean.override.mockito.MockitoBean;\nimport org.springframework.test.web.servlet.MockMvc;\n\n@WebMvcTest(ClienteController.class)\n@Import({SeguridadConfig.class, ClienteControllerValidacionTest.Configuracion.class})\nclass ClienteControllerValidacionTest {\n\n    private static final String SUJETO = \"6f1c2e7a-9a3b-4c1d-8e2f-1a2b3c4d5e6f\";\n\n    @TestConfiguration\n    @EnableWebSecurity\n    static class Configuracion {\n    }\n\n    @Autowired\n    private MockMvc mvc;\n\n    @MockitoBean\n    private ClienteService servicio;\n\n    @MockitoBean\n    private Auditoria auditoria;\n\n    @MockitoBean\n    private Presentacion presentacion;\n\n    @MockitoBean\n    private RevocacionSesiones revocaciones;\n\n    @Test\n    void rfcDeMasDe13CaracteresDa400() throws Exception {\n        mvc.perform(get(\"/v1/clientes\").param(\"rfc\", \"X\".repeat(14))\n                        .with(jwt().jwt(j -> j.subject(SUJETO)).authorities(new SimpleGrantedAuthority(\"ROLE_VENTAS\"))))\n                .andExpect(status().isBadRequest());\n    }\n\n    @Test\n    void nombreDeMasDe200CaracteresDa400() throws Exception {\n        mvc.perform(get(\"/v1/clientes\").param(\"nombre\", \"A\".repeat(201))\n                        .with(jwt().jwt(j -> j.subject(SUJETO)).authorities(new SimpleGrantedAuthority(\"ROLE_VENTAS\"))))\n                .andExpect(status().isBadRequest());\n    }\n\n    @Test\n    void nombreDe200CaracteresEsValido() throws Exception {\n        when(servicio.buscar(any(), any(), any())).thenReturn(new PageImpl<>(List.of()));\n        mvc.perform(get(\"/v1/clientes\").param(\"nombre\", \"A\".repeat(200))\n                        .with(jwt().jwt(j -> j.subject(SUJETO)).authorities(new SimpleGrantedAuthority(\"ROLE_VENTAS\"))))\n                .andExpect(status().isOk());\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/clientes/api/MascaraTest.java": "package com.mx.josesaid.develop.clientes.api;\n\nimport static org.assertj.core.api.Assertions.assertThat;\n\nimport org.junit.jupiter.api.Test;\n\nclass MascaraTest {\n\n    @Test\n    void enmascaraRfcConservandoTresPrimerosYDosUltimos() {\n        assertThat(Mascara.rfc(\"IDE900101XY1\")).isEqualTo(\"IDE\" + \"*\".repeat(7) + \"Y1\");\n    }\n\n    @Test\n    void enmascaraCorreoConservandoPrimeraLetraYDominio() {\n        assertThat(Mascara.correo(\"ana.lopez@ejemplo.mx\")).isEqualTo(\"a***@ejemplo.mx\");\n    }\n\n    @Test\n    void enmascaraNombreDejandoSoloLaPrimeraLetra() {\n        assertThat(Mascara.nombre(\"Ana López\")).isEqualTo(\"A***\");\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/clientes/domain/ConsentimientoTest.java": "package com.mx.josesaid.develop.clientes.domain;\n\nimport static org.assertj.core.api.Assertions.assertThat;\n\nimport java.time.Instant;\nimport java.time.LocalDate;\nimport java.util.UUID;\nimport org.junit.jupiter.api.Test;\n\nclass ConsentimientoTest {\n\n    private static final Instant AHORA = Instant.parse(\"2026-10-29T18:00:00Z\");\n\n    private Consentimiento otorgado(LocalDate vigencia) {\n        return Consentimiento.otorgado(UUID.randomUUID(), UUID.randomUUID(), \"Comunicaciones comerciales\",\n                AHORA, MedioConsentimiento.FORMULARIO, vigencia, AHORA);\n    }\n\n    @Test\n    void revocarEsIdempotenteYSoloEmiteLaPrimeraVez() {\n        Consentimiento consentimiento = otorgado(null);\n\n        assertThat(consentimiento.revocar(AHORA)).isTrue();\n        assertThat(consentimiento.revocar(AHORA.plusSeconds(60))).isFalse();\n        assertThat(consentimiento.getRevocadoAt()).isEqualTo(AHORA);\n    }\n\n    @Test\n    void noEstaVigenteDespuesDeSuVigencia() {\n        Consentimiento consentimiento = otorgado(LocalDate.parse(\"2027-10-29\"));\n\n        assertThat(consentimiento.estaVigente(LocalDate.parse(\"2027-10-29\"))).isTrue();\n        assertThat(consentimiento.estaVigente(LocalDate.parse(\"2027-10-30\"))).isFalse();\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/clientes/domain/EstatusClienteTest.java": "package com.mx.josesaid.develop.clientes.domain;\n\nimport static org.assertj.core.api.Assertions.assertThat;\n\nimport org.junit.jupiter.api.Test;\n\nclass EstatusClienteTest {\n\n    @Test\n    void activoYSuspendidoPuedenAlternarse() {\n        assertThat(EstatusCliente.ACTIVO.puedePasarA(EstatusCliente.SUSPENDIDO)).isTrue();\n        assertThat(EstatusCliente.SUSPENDIDO.puedePasarA(EstatusCliente.ACTIVO)).isTrue();\n    }\n\n    @Test\n    void bajaEsTerminal() {\n        assertThat(EstatusCliente.BAJA.puedePasarA(EstatusCliente.ACTIVO)).isFalse();\n        assertThat(EstatusCliente.ACTIVO.puedePasarA(EstatusCliente.BAJA)).isTrue();\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/clientes/domain/EstatusProspectoTest.java": "package com.mx.josesaid.develop.clientes.domain;\n\nimport static org.assertj.core.api.Assertions.assertThat;\n\nimport org.junit.jupiter.api.Test;\n\nclass EstatusProspectoTest {\n\n    @Test\n    void avanzaEnOrdenNuevoContactadoCalificado() {\n        assertThat(EstatusProspecto.NUEVO.puedePasarA(EstatusProspecto.CONTACTADO)).isTrue();\n        assertThat(EstatusProspecto.CONTACTADO.puedePasarA(EstatusProspecto.CALIFICADO)).isTrue();\n        assertThat(EstatusProspecto.NUEVO.puedePasarA(EstatusProspecto.CALIFICADO)).isFalse();\n    }\n\n    @Test\n    void convertidoSoloSeAlcanzaPorConversion() {\n        assertThat(EstatusProspecto.CALIFICADO.puedePasarA(EstatusProspecto.CONVERTIDO)).isFalse();\n    }\n\n    @Test\n    void perdidoSoloDesdeEstadosAbiertos() {\n        assertThat(EstatusProspecto.CONTACTADO.puedePasarA(EstatusProspecto.PERDIDO)).isTrue();\n        assertThat(EstatusProspecto.PERDIDO.puedePasarA(EstatusProspecto.NUEVO)).isFalse();\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/clientes/domain/FechasNegocioTest.java": "package com.mx.josesaid.develop.clientes.domain;\n\nimport static org.junit.jupiter.api.Assertions.assertEquals;\n\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.time.LocalDate;\nimport java.time.ZoneOffset;\nimport org.junit.jupiter.api.Test;\n\nclass FechasNegocioTest {\n\n    @Test\n    void usaLaFechaDeMexicoAunqueEnUtcYaSeaOtroDia() {\n        // 2026-11-08 22:34 hora de México = 2026-11-09 04:34 UTC\n        Clock reloj = Clock.fixed(Instant.parse(\"2026-11-09T04:34:00Z\"), ZoneOffset.UTC);\n\n        assertEquals(LocalDate.of(2026, 11, 8), FechasNegocio.hoy(reloj));\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/clientes/domain/InteraccionTest.java": "package com.mx.josesaid.develop.clientes.domain;\n\nimport static org.assertj.core.api.Assertions.assertThat;\n\nimport java.time.Instant;\nimport java.util.UUID;\nimport org.junit.jupiter.api.Test;\n\nclass InteraccionTest {\n\n    @Test\n    void nuevaGuardaLosDatosRecibidos() {\n        UUID id = UUID.randomUUID();\n        UUID clienteId = UUID.randomUUID();\n        UUID responsableId = UUID.randomUUID();\n        Instant fecha = Instant.parse(\"2026-11-01T15:30:00Z\");\n        Instant ahora = Instant.parse(\"2026-11-02T10:00:00Z\");\n\n        Interaccion i = Interaccion.nueva(id, clienteId, TipoInteraccion.VISITA, fecha, responsableId,\n                \"Revisión de contrato\", ahora);\n\n        assertThat(i.getId()).isEqualTo(id);\n        assertThat(i.getClienteId()).isEqualTo(clienteId);\n        assertThat(i.getTipo()).isEqualTo(TipoInteraccion.VISITA);\n        assertThat(i.getFecha()).isEqualTo(fecha);\n        assertThat(i.getResponsableId()).isEqualTo(responsableId);\n        assertThat(i.getResumen()).isEqualTo(\"Revisión de contrato\");\n    }\n\n    @Test\n    void nuevaQuitaEspaciosAlrededorDelResumen() {\n        Interaccion i = Interaccion.nueva(UUID.randomUUID(), UUID.randomUUID(), TipoInteraccion.LLAMADA,\n                Instant.now(), UUID.randomUUID(), \"   seguimiento de cobro  \\n\", Instant.now());\n\n        assertThat(i.getResumen()).isEqualTo(\"seguimiento de cobro\");\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/clientes/domain/ProspectoTest.java": "package com.mx.josesaid.develop.clientes.domain;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.assertj.core.api.Assertions.assertThatThrownBy;\n\nimport com.mx.josesaid.develop.clientes.infrastructure.crypto.ClavesCripto;\nimport java.time.Instant;\nimport java.time.LocalDate;\nimport java.util.UUID;\nimport org.junit.jupiter.api.BeforeAll;\nimport org.junit.jupiter.api.Test;\n\nclass ProspectoTest {\n\n    private static final Instant AHORA = Instant.parse(\"2026-10-29T18:00:00Z\");\n\n    @BeforeAll\n    static void claves() {\n        ClavesCripto.configurar(new byte[32], new byte[32]);\n    }\n\n    private Prospecto nuevo() {\n        return Prospecto.nuevo(UUID.randomUUID(), \"Ana López\", \"ana@ejemplo.mx\", null,\n                Fuente.CAMPANA, LocalDate.parse(\"2026-10-29\"), AHORA);\n    }\n\n    @Test\n    void nuevoProspectoInicia_enNuevoConIndicesCalculados() {\n        Prospecto prospecto = nuevo();\n\n        assertThat(prospecto.getEstatus()).isEqualTo(EstatusProspecto.NUEVO);\n        assertThat(prospecto.getCorreoHash()).hasSize(64);\n        assertThat(prospecto.getNombreHash()).hasSize(64);\n    }\n\n    @Test\n    void noSePuedeConvertirDesdeNuevo() {\n        Prospecto prospecto = nuevo();\n\n        assertThatThrownBy(() -> prospecto.marcarConvertido(AHORA))\n                .isInstanceOf(TransicionInvalidaException.class);\n    }\n\n    @Test\n    void conviertePorqueEstaCalificado() {\n        Prospecto prospecto = nuevo();\n        prospecto.cambiarEstatus(EstatusProspecto.CONTACTADO, AHORA);\n        prospecto.cambiarEstatus(EstatusProspecto.CALIFICADO, AHORA);\n\n        prospecto.marcarConvertido(AHORA);\n\n        assertThat(prospecto.getEstatus()).isEqualTo(EstatusProspecto.CONVERTIDO);\n        assertThat(prospecto.getFechaConversion()).isEqualTo(AHORA);\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/clientes/infrastructure/crypto/CampoCifradoConverterTest.java": "package com.mx.josesaid.develop.clientes.infrastructure.crypto;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.assertj.core.api.Assertions.assertThatThrownBy;\n\nimport java.nio.ByteBuffer;\nimport java.nio.charset.StandardCharsets;\nimport java.security.SecureRandom;\nimport java.util.Base64;\nimport java.util.Map;\nimport javax.crypto.Cipher;\nimport javax.crypto.spec.GCMParameterSpec;\nimport javax.crypto.spec.SecretKeySpec;\nimport org.junit.jupiter.api.BeforeEach;\nimport org.junit.jupiter.api.Test;\n\nclass CampoCifradoConverterTest {\n\n    private final CampoCifradoConverter convertidor = new CampoCifradoConverter();\n    private final SecureRandom aleatorio = new SecureRandom();\n    private byte[] clave1;\n    private byte[] clave2;\n\n    @BeforeEach\n    void configurarClaves() {\n        clave1 = bytesAleatorios();\n        clave2 = bytesAleatorios();\n        ClavesCripto.configurar(Map.of(1, clave1), 1, bytesAleatorios());\n    }\n\n    @Test\n    void cifraConLaVersionActivaYLeeDeVuelta() {\n        String columna = convertidor.convertToDatabaseColumn(\"juan@ejemplo.mx\");\n\n        assertThat(columna).startsWith(\"v1:\");\n        assertThat(convertidor.convertToEntityAttribute(columna)).isEqualTo(\"juan@ejemplo.mx\");\n    }\n\n    @Test\n    void cadenaNulaSeMantieneNula() {\n        assertThat(convertidor.convertToDatabaseColumn(null)).isNull();\n        assertThat(convertidor.convertToEntityAttribute(null)).isNull();\n    }\n\n    @Test\n    void leeValorAntiguoSinPrefijoComoVersionUno() {\n        String antiguo = cifrarSinPrefijo(\"PEGJ800101AAA\", clave1);\n\n        assertThat(convertidor.convertToEntityAttribute(antiguo)).isEqualTo(\"PEGJ800101AAA\");\n    }\n\n    @Test\n    void escribeConLaVersionActivaNueva() {\n        ClavesCripto.configurar(Map.of(1, clave1, 2, clave2), 2, bytesAleatorios());\n\n        String columna = convertidor.convertToDatabaseColumn(\"dato\");\n\n        assertThat(columna).startsWith(\"v2:\");\n        assertThat(convertidor.convertToEntityAttribute(columna)).isEqualTo(\"dato\");\n    }\n\n    @Test\n    void leeValorDeVersionAnteriorAunqueLaActivaSeaOtra() {\n        String viejo = convertidor.convertToDatabaseColumn(\"antes de rotar\");\n        ClavesCripto.configurar(Map.of(1, clave1, 2, clave2), 2, bytesAleatorios());\n\n        assertThat(viejo).startsWith(\"v1:\");\n        assertThat(convertidor.convertToEntityAttribute(viejo)).isEqualTo(\"antes de rotar\");\n    }\n\n    @Test\n    void versionNoConfiguradaFalla() {\n        String columna = \"v9:\" + Base64.getEncoder().encodeToString(new byte[40]);\n\n        assertThatThrownBy(() -> convertidor.convertToEntityAttribute(columna))\n                .isInstanceOf(IllegalStateException.class)\n                .hasMessageContaining(\"Versión de clave de cifrado no configurada: 9\");\n    }\n\n    @Test\n    void versionActivaDebeEstarConfigurada() {\n        assertThatThrownBy(() -> ClavesCripto.configurar(Map.of(1, clave1), 2, bytesAleatorios()))\n                .isInstanceOf(IllegalStateException.class);\n    }\n\n    private byte[] bytesAleatorios() {\n        byte[] bytes = new byte[32];\n        aleatorio.nextBytes(bytes);\n        return bytes;\n    }\n\n    /** Replica el formato anterior (sin prefijo) para verificar la compatibilidad. */\n    private String cifrarSinPrefijo(String texto, byte[] clave) {\n        try {\n            byte[] iv = new byte[12];\n            aleatorio.nextBytes(iv);\n            Cipher cipher = Cipher.getInstance(\"AES/GCM/NoPadding\");\n            cipher.init(Cipher.ENCRYPT_MODE, new SecretKeySpec(clave, \"AES\"), new GCMParameterSpec(128, iv));\n            byte[] cifrado = cipher.doFinal(texto.getBytes(StandardCharsets.UTF_8));\n            byte[] salida = ByteBuffer.allocate(iv.length + cifrado.length).put(iv).put(cifrado).array();\n            return Base64.getEncoder().encodeToString(salida);\n        } catch (Exception e) {\n            throw new IllegalStateException(e);\n        }\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/clientes/infrastructure/crypto/RecifradorCamposRunnerTest.java": "package com.mx.josesaid.develop.clientes.infrastructure.crypto;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.mockito.ArgumentMatchers.any;\nimport static org.mockito.ArgumentMatchers.anyInt;\nimport static org.mockito.ArgumentMatchers.anyString;\nimport static org.mockito.ArgumentMatchers.eq;\nimport static org.mockito.Mockito.mock;\nimport static org.mockito.Mockito.never;\nimport static org.mockito.Mockito.times;\nimport static org.mockito.Mockito.verify;\nimport static org.mockito.Mockito.when;\n\nimport java.security.SecureRandom;\nimport java.util.List;\nimport java.util.Map;\nimport org.junit.jupiter.api.BeforeEach;\nimport org.junit.jupiter.api.Test;\nimport org.mockito.ArgumentCaptor;\nimport org.springframework.boot.ApplicationArguments;\n\nclass RecifradorCamposRunnerTest {\n\n    private final SecureRandom aleatorio = new SecureRandom();\n    private final CampoCifradoConverter convertidor = new CampoCifradoConverter();\n    private byte[] clave1;\n    private byte[] clave2;\n    private RecifradorJdbc almacen;\n    private RecifradorCamposRunner runner;\n\n    @BeforeEach\n    void preparar() {\n        clave1 = bytes();\n        clave2 = bytes();\n        ClavesCripto.configurar(Map.of(1, clave1), 1, bytes());\n        almacen = mock(RecifradorJdbc.class);\n        runner = new RecifradorCamposRunner(almacen);\n    }\n\n    @Test\n    void sinFilasPendientesNoActualizaNada() {\n        when(almacen.pendientes(anyString(), anyString(), anyInt())).thenReturn(List.of());\n\n        runner.run(mock(ApplicationArguments.class));\n\n        verify(almacen, times(7)).pendientes(anyString(), anyString(), eq(500));\n        verify(almacen, never()).actualizar(anyString(), anyString(), any(), anyString(), anyString());\n    }\n\n    @Test\n    void recifraLaFilaViejaConLaVersionActiva() {\n        String viejo = convertidor.convertToDatabaseColumn(\"ana@empresa.mx\");\n        ClavesCripto.configurar(Map.of(1, clave1, 2, clave2), 2, bytes());\n\n        when(almacen.pendientes(anyString(), anyString(), anyInt())).thenReturn(List.of());\n        when(almacen.pendientes(eq(\"contacto\"), eq(\"correo_cifrado\"), anyInt()))\n                .thenReturn(List.of(new RecifradorPorLotes.Fila(1L, viejo)))\n                .thenReturn(List.of());\n        when(almacen.actualizar(eq(\"contacto\"), eq(\"correo_cifrado\"), eq(1L), eq(viejo), anyString()))\n                .thenReturn(true);\n\n        runner.run(mock(ApplicationArguments.class));\n\n        ArgumentCaptor<String> nuevo = ArgumentCaptor.forClass(String.class);\n        verify(almacen).actualizar(eq(\"contacto\"), eq(\"correo_cifrado\"), eq(1L), eq(viejo), nuevo.capture());\n        assertThat(nuevo.getValue()).startsWith(\"v2:\");\n        assertThat(convertidor.convertToEntityAttribute(nuevo.getValue())).isEqualTo(\"ana@empresa.mx\");\n    }\n\n    private byte[] bytes() {\n        byte[] b = new byte[32];\n        aleatorio.nextBytes(b);\n        return b;\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/clientes/infrastructure/crypto/RecifradorPorLotesTest.java": "package com.mx.josesaid.develop.clientes.infrastructure.crypto;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.assertj.core.api.Assertions.assertThatThrownBy;\n\nimport java.security.SecureRandom;\nimport java.util.ArrayList;\nimport java.util.LinkedHashMap;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.UUID;\nimport org.junit.jupiter.api.BeforeEach;\nimport org.junit.jupiter.api.Test;\n\nclass RecifradorPorLotesTest {\n\n    private final CampoCifradoConverter convertidor = new CampoCifradoConverter();\n    private final SecureRandom aleatorio = new SecureRandom();\n    private byte[] clave1;\n    private byte[] clave2;\n\n    @BeforeEach\n    void claves() {\n        clave1 = bytes();\n        clave2 = bytes();\n        ClavesCripto.configurar(Map.of(1, clave1), 1, bytes());\n    }\n\n    @Test\n    void recifraTodasLasFilasPendientesYNoQuedaNinguna() {\n        String viejo1 = convertidor.convertToDatabaseColumn(\"ana@empresa.mx\");\n        String viejo2 = convertidor.convertToDatabaseColumn(\"luis@empresa.mx\");\n        ClavesCripto.configurar(Map.of(1, clave1, 2, clave2), 2, bytes());\n        AlmacenEnMemoria almacen = new AlmacenEnMemoria();\n        almacen.agregar(UUID.randomUUID(), viejo1);\n        almacen.agregar(UUID.randomUUID(), viejo2);\n\n        int recifradas = recifrador(almacen, 10).ejecutar(\"contacto\", \"correo_cifrado\");\n\n        assertThat(recifradas).isEqualTo(2);\n        assertThat(almacen.valores()).allSatisfy(v -> assertThat(v).startsWith(\"v2:\"));\n        assertThat(almacen.valores()).allSatisfy(v -> assertThat(convertidor.convertToEntityAttribute(v))\n                .isIn(\"ana@empresa.mx\", \"luis@empresa.mx\"));\n    }\n\n    @Test\n    void respetaElTamanoDeLote() {\n        AlmacenEnMemoria almacen = new AlmacenEnMemoria();\n        for (int i = 0; i < 5; i++) {\n            almacen.agregar(UUID.randomUUID(), convertidor.convertToDatabaseColumn(\"dato\" + i));\n        }\n        ClavesCripto.configurar(Map.of(1, clave1, 2, clave2), 2, bytes());\n\n        recifrador(almacen, 2).ejecutar(\"cliente\", \"rfc_cifrado\");\n\n        assertThat(almacen.limitesPedidos).containsOnly(2);\n        assertThat(almacen.valores()).allSatisfy(v -> assertThat(v).startsWith(\"v2:\"));\n    }\n\n    @Test\n    void omiteLasFilasYaEnLaVersionActiva() {\n        ClavesCripto.configurar(Map.of(1, clave1, 2, clave2), 2, bytes());\n        AlmacenEnMemoria almacen = new AlmacenEnMemoria();\n        String yaNueva = convertidor.convertToDatabaseColumn(\"ya nueva\");\n        almacen.agregar(UUID.randomUUID(), yaNueva);\n\n        int recifradas = recifrador(almacen, 10).ejecutar(\"cliente\", \"rfc_cifrado\");\n\n        assertThat(recifradas).isZero();\n        assertThat(almacen.valores()).containsExactly(yaNueva);\n    }\n\n    @Test\n    void reanudarDespuesDeUnCorteNoDuplicaNiPierde() {\n        String viejo1 = convertidor.convertToDatabaseColumn(\"uno\");\n        String viejo2 = convertidor.convertToDatabaseColumn(\"dos\");\n        ClavesCripto.configurar(Map.of(1, clave1, 2, clave2), 2, bytes());\n        AlmacenEnMemoria almacen = new AlmacenEnMemoria();\n        almacen.agregar(UUID.randomUUID(), viejo1);\n        almacen.agregar(UUID.randomUUID(), viejo2);\n        almacen.fallarEnActualizacion = 2;\n\n        assertThatThrownBy(() -> recifrador(almacen, 1).ejecutar(\"interaccion\", \"resumen_cifrado\"))\n                .isInstanceOf(IllegalStateException.class);\n        almacen.fallarEnActualizacion = 0;\n        int segundaCorrida = recifrador(almacen, 1).ejecutar(\"interaccion\", \"resumen_cifrado\");\n\n        assertThat(segundaCorrida).isEqualTo(1);\n        assertThat(almacen.valores()).allSatisfy(v -> assertThat(v).startsWith(\"v2:\"));\n    }\n\n    @Test\n    void siUnaFilaCambiaDuranteElProcesoSeAvisa() {\n        AlmacenEnMemoria almacen = new AlmacenEnMemoria();\n        almacen.agregar(UUID.randomUUID(), convertidor.convertToDatabaseColumn(\"x\"));\n        ClavesCripto.configurar(Map.of(1, clave1, 2, clave2), 2, bytes());\n        almacen.rechazarActualizacion = true;\n\n        assertThatThrownBy(() -> recifrador(almacen, 10).ejecutar(\"contacto\", \"nombre_cifrado\"))\n                .isInstanceOf(IllegalStateException.class)\n                .hasMessageContaining(\"cambió durante el proceso\");\n    }\n\n    @Test\n    void tamanoDeLoteDebeSerPositivo() {\n        assertThatThrownBy(() -> new RecifradorPorLotes(new AlmacenEnMemoria(), 0, v -> v))\n                .isInstanceOf(IllegalArgumentException.class);\n    }\n\n    @Test\n    void versionDeIdentificaPrefijoOSinPrefijo() {\n        assertThat(CampoCifradoConverter.versionDe(\"v7:AAAA\")).isEqualTo(7);\n        assertThat(CampoCifradoConverter.versionDe(\"AAAA\")).isEqualTo(1);\n    }\n\n    private RecifradorPorLotes recifrador(RecifradorPorLotes.Almacen almacen, int lote) {\n        return new RecifradorPorLotes(almacen, lote,\n                valor -> convertidor.convertToDatabaseColumn(convertidor.convertToEntityAttribute(valor)));\n    }\n\n    private byte[] bytes() {\n        byte[] b = new byte[32];\n        aleatorio.nextBytes(b);\n        return b;\n    }\n\n    /** Almacén en memoria con las mismas reglas que la consulta JDBC. */\n    private static final class AlmacenEnMemoria implements RecifradorPorLotes.Almacen {\n        private final Map<Object, String> filas = new LinkedHashMap<>();\n        private final List<Integer> limitesPedidos = new ArrayList<>();\n        private int fallarEnActualizacion;\n        private boolean rechazarActualizacion;\n        private int actualizaciones;\n\n        void agregar(Object id, String valor) {\n            filas.put(id, valor);\n        }\n\n        List<String> valores() {\n            return new ArrayList<>(filas.values());\n        }\n\n        @Override\n        public List<RecifradorPorLotes.Fila> pendientes(String tabla, String columna, int limite) {\n            limitesPedidos.add(limite);\n            String prefijo = \"v\" + ClavesCripto.versionActiva() + \":\";\n            List<RecifradorPorLotes.Fila> salida = new ArrayList<>();\n            for (Map.Entry<Object, String> e : filas.entrySet()) {\n                if (!e.getValue().startsWith(prefijo) && salida.size() < limite) {\n                    salida.add(new RecifradorPorLotes.Fila(e.getKey(), e.getValue()));\n                }\n            }\n            return salida;\n        }\n\n        @Override\n        public boolean actualizar(String tabla, String columna, Object id, String valorAnterior, String valorNuevo) {\n            if (fallarEnActualizacion > 0 && ++actualizaciones == fallarEnActualizacion) {\n                throw new IllegalStateException(\"corte simulado\");\n            }\n            if (rechazarActualizacion || !valorAnterior.equals(filas.get(id))) {\n                return false;\n            }\n            filas.put(id, valorNuevo);\n            return true;\n        }\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/clientes/infrastructure/indicadores/PublicadorIndicadoresClientesIT.java": "package com.mx.josesaid.develop.clientes.infrastructure.indicadores;\n\nimport static org.junit.jupiter.api.Assertions.assertEquals;\n\nimport com.jayway.jsonpath.JsonPath;\nimport java.time.Duration;\nimport java.time.LocalDate;\nimport java.time.YearMonth;\nimport java.time.ZoneId;\nimport java.util.Collections;\nimport java.util.Properties;\nimport java.util.UUID;\nimport org.apache.kafka.clients.consumer.ConsumerConfig;\nimport org.apache.kafka.clients.consumer.KafkaConsumer;\nimport org.apache.kafka.common.serialization.StringDeserializer;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.boot.test.context.SpringBootTest;\nimport org.springframework.boot.testcontainers.service.connection.ServiceConnection;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.springframework.test.context.ActiveProfiles;\nimport org.testcontainers.junit.jupiter.Container;\nimport org.testcontainers.junit.jupiter.Testcontainers;\nimport org.testcontainers.kafka.KafkaContainer;\nimport org.testcontainers.postgresql.PostgreSQLContainer;\n\n/** Integración con PostgreSQL y Kafka reales (Testcontainers). Requiere Docker; corre con 'mvn verify'. */\n@SpringBootTest\n@ActiveProfiles(\"test\")\n@Testcontainers\nclass PublicadorIndicadoresClientesIT {\n\n    @Container\n    @ServiceConnection\n    static PostgreSQLContainer postgres = new PostgreSQLContainer(\"postgres:17-alpine\");\n\n    @Container\n    @ServiceConnection\n    static KafkaContainer kafka = new KafkaContainer(\"apache/kafka:4.0.0\");\n\n    @Autowired\n    private JdbcTemplate jdbc;\n\n    @Autowired\n    private PublicadorIndicadoresClientes publicador;\n\n    private static final ZoneId ZONA = ZoneId.of(\"America/Mexico_City\");\n\n    @Test\n    void clientesNuevosDelMesCuentaSoloLasAltasDelPeriodo() {\n        LocalDate hoy = LocalDate.now(ZONA);\n        String periodo = YearMonth.from(hoy).toString();\n        cliente(hoy, \"ACTIVO\");\n        cliente(hoy, \"SUSPENDIDO\");\n        cliente(hoy.minusMonths(1), \"ACTIVO\");  // excluido: alta del mes anterior\n\n        publicador.publicarPeriodo(periodo);\n\n        String clave = PublicadorIndicadoresClientes.AREA + \"|\" + PublicadorIndicadoresClientes.NOMBRE + \"|\" + periodo;\n        String payload = leerIndicador(clave);\n        assertEquals(\"VENTAS_ATENCION_CLIENTES\", JsonPath.read(payload, \"$.area\"));\n        assertEquals(2.0, ((Number) JsonPath.read(payload, \"$.valor\")).doubleValue(), 0.001);\n    }\n\n    private void cliente(LocalDate fechaAlta, String estatus) {\n        jdbc.update(\"\"\"\n                INSERT INTO cliente (id, razon_social, rfc_cifrado, rfc_hash, estatus, fecha_alta,\n                                     created_at, updated_at, version)\n                VALUES (?, 'Cliente SA', 'cifrado', ?, ?, ?, now(), now(), 0)\n                \"\"\", UUID.randomUUID(), UUID.randomUUID().toString(), estatus,\n                java.sql.Date.valueOf(fechaAlta));\n    }\n\n    private String leerIndicador(String clave) {\n        try (KafkaConsumer<String, String> consumidor = new KafkaConsumer<>(propiedades())) {\n            consumidor.subscribe(Collections.singletonList(\"indicadores-areas\"));\n            long limite = System.currentTimeMillis() + 30_000;\n            while (System.currentTimeMillis() < limite) {\n                for (var registro : consumidor.poll(Duration.ofMillis(500))) {\n                    if (clave.equals(registro.key())) {\n                        return registro.value();\n                    }\n                }\n            }\n            throw new AssertionError(\"No llegó el indicador \" + clave);\n        }\n    }\n\n    private Properties propiedades() {\n        Properties p = new Properties();\n        p.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, kafka.getBootstrapServers());\n        p.put(ConsumerConfig.GROUP_ID_CONFIG, \"test-\" + UUID.randomUUID());\n        p.put(ConsumerConfig.AUTO_OFFSET_RESET_CONFIG, \"earliest\");\n        p.put(ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class);\n        p.put(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class);\n        return p;\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/clientes/integracion/FlujoClientesIT.java": "package com.mx.josesaid.develop.clientes.integracion;\n\nimport static org.hamcrest.Matchers.containsString;\nimport static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.jwt;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.patch;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;\nimport static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;\nimport static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;\n\nimport java.util.regex.Matcher;\nimport java.util.regex.Pattern;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;\nimport org.springframework.boot.test.context.SpringBootTest;\nimport org.springframework.boot.test.context.TestConfiguration;\nimport org.springframework.boot.testcontainers.service.connection.ServiceConnection;\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Primary;\nimport org.springframework.security.core.authority.SimpleGrantedAuthority;\nimport org.springframework.security.oauth2.jwt.JwtDecoder;\nimport org.springframework.security.oauth2.jwt.JwtException;\nimport org.springframework.test.context.ActiveProfiles;\nimport org.springframework.test.web.servlet.MockMvc;\nimport org.springframework.test.web.servlet.MvcResult;\nimport org.springframework.test.web.servlet.request.RequestPostProcessor;\nimport org.testcontainers.kafka.KafkaContainer;\nimport org.testcontainers.junit.jupiter.Container;\nimport org.testcontainers.junit.jupiter.Testcontainers;\nimport org.testcontainers.postgresql.PostgreSQLContainer;\nimport org.testcontainers.utility.DockerImageName;\n\n/**\n * Pruebas de integración con PostgreSQL 17 y Kafka reales (Testcontainers). Requieren Docker en ejecución.\n */\n@SpringBootTest\n@AutoConfigureMockMvc\n@ActiveProfiles(\"test\")\n@Testcontainers\nclass FlujoClientesIT {\n\n    private static final String VENTAS = \"VENTAS\";\n    private static final String ADMIN = \"ADMIN\";\n    private static final String GERENTE = \"VENTAS\";\n    private static final Pattern ID = Pattern.compile(\"\\\"id\\\":\\\"([0-9a-f-]{36})\\\"\");\n\n    @Container\n    @ServiceConnection\n    static PostgreSQLContainer postgres = new PostgreSQLContainer(DockerImageName.parse(\"postgres:17-alpine\"));\n\n    @Container\n    @ServiceConnection\n    static KafkaContainer kafka = new KafkaContainer(\"apache/kafka:4.0.0\");\n\n    @Autowired\n    private MockMvc mvc;\n\n    /** Las pruebas usan jwt() de spring-security-test; este decodificador nunca se invoca. */\n    @TestConfiguration\n    static class ConfiguracionPruebas {\n\n        @Bean\n        @Primary\n        JwtDecoder jwtDecoderPruebas() {\n            return token -> {\n                throw new JwtException(\"No se usa en pruebas de integración\");\n            };\n        }\n    }\n\n    private static RequestPostProcessor como(String rol) {\n        return jwt().jwt(j -> j.subject(\"8f3c2a1e-6b4d-4e5f-9a7b-1c2d3e4f5a6b\"))\n                .authorities(new SimpleGrantedAuthority(\"ROLE_\" + rol));\n    }\n\n    private static String extraerId(MvcResult resultado) throws Exception {\n        Matcher m = ID.matcher(resultado.getResponse().getContentAsString());\n        m.find();\n        return m.group(1);\n    }\n\n    @Test\n    void conversionDeProspectoCalificadoCreaClienteActivo() throws Exception {\n        MvcResult prospecto = mvc.perform(post(\"/v1/prospectos\").with(como(VENTAS))\n                        .contentType(\"application/json\")\n                        .content(\"\"\"\n                                {\"nombre\":\"Ana Flujo\",\"correo\":\"ana.flujo@ejemplo.mx\",\"fuente\":\"CAMPANA\"}\n                                \"\"\"))\n                .andExpect(status().isCreated())\n                .andReturn();\n        String prospectoId = extraerId(prospecto);\n\n        mvc.perform(patch(\"/v1/prospectos/\" + prospectoId + \"/estatus\").with(como(VENTAS))\n                        .contentType(\"application/json\").content(\"{\\\"estatus\\\":\\\"CONTACTADO\\\"}\"))\n                .andExpect(status().isOk());\n        mvc.perform(patch(\"/v1/prospectos/\" + prospectoId + \"/estatus\").with(como(VENTAS))\n                        .contentType(\"application/json\").content(\"{\\\"estatus\\\":\\\"CALIFICADO\\\"}\"))\n                .andExpect(status().isOk());\n\n        mvc.perform(post(\"/v1/prospectos/\" + prospectoId + \"/conversion\").with(como(VENTAS))\n                        .contentType(\"application/json\").content(\"\"\"\n                                {\"razonSocial\":\"Industrias Flujo SA de CV\",\"rfc\":\"IFL900101XY1\",\n                                 \"contactoPrincipal\":{\"nombre\":\"Luis Pérez\",\"correo\":\"luis.flujo@demo.mx\",\"rol\":\"COMPRAS\"}}\n                                \"\"\"))\n                .andExpect(status().isCreated())\n                .andExpect(jsonPath(\"$.estatus\").value(\"ACTIVO\"))\n                .andExpect(jsonPath(\"$.rfc\").value(containsString(\"*\")));\n    }\n\n    @Test\n    void segundoClienteActivoConMismoRfcRespondeConflicto() throws Exception {\n        String cuerpo = \"\"\"\n                {\"razonSocial\":\"Comercial Rfc SA\",\"rfc\":\"CRF900101AB2\",\n                 \"contactoPrincipal\":{\"nombre\":\"Marta Ruiz\",\"correo\":\"marta.rfc@norte.mx\",\"rol\":\"PAGOS\"}}\n                \"\"\";\n        mvc.perform(post(\"/v1/clientes\").with(como(ADMIN)).contentType(\"application/json\").content(cuerpo))\n                .andExpect(status().isCreated());\n\n        mvc.perform(post(\"/v1/clientes\").with(como(ADMIN)).contentType(\"application/json\").content(cuerpo))\n                .andExpect(status().isConflict())\n                .andExpect(jsonPath(\"$.type\").value(\"urn:clientes:error:rfc-duplicado\"))\n                .andExpect(jsonPath(\"$.clienteExistenteId\").exists());\n    }\n\n    @Test\n    void clienteDadoDeBajaNoSeReactiva() throws Exception {\n        MvcResult alta = mvc.perform(post(\"/v1/clientes\").with(como(ADMIN)).contentType(\"application/json\").content(\"\"\"\n                        {\"razonSocial\":\"Baja Test SA\",\"rfc\":\"BAJ900101AB3\",\n                         \"contactoPrincipal\":{\"nombre\":\"Jorge Baja\",\"correo\":\"jorge.baja@test.mx\",\"rol\":\"ASISTENCIA\"}}\n                        \"\"\"))\n                .andExpect(status().isCreated())\n                .andReturn();\n        String clienteId = extraerId(alta);\n\n        mvc.perform(patch(\"/v1/clientes/\" + clienteId + \"/estatus\").with(como(ADMIN))\n                        .contentType(\"application/json\").content(\"{\\\"estatus\\\":\\\"BAJA\\\"}\"))\n                .andExpect(status().isOk());\n\n        mvc.perform(patch(\"/v1/clientes/\" + clienteId + \"/estatus\").with(como(ADMIN))\n                        .contentType(\"application/json\").content(\"{\\\"estatus\\\":\\\"ACTIVO\\\"}\"))\n                .andExpect(status().isConflict())\n                .andExpect(jsonPath(\"$.type\").value(\"urn:clientes:error:transicion-invalida\"));\n    }\n\n    @Test\n    void ventasConsultaMetricasDelMes() throws Exception {\n        mvc.perform(get(\"/v1/metricas/conversion\").param(\"mes\", \"2026-10\").with(como(VENTAS)))\n                .andExpect(status().isOk());\n    }\n\n    @Test\n    void gerenteConsultaMetricasDelMes() throws Exception {\n        mvc.perform(get(\"/v1/metricas/conversion\").param(\"mes\", \"2026-10\").with(como(GERENTE)))\n                .andExpect(status().isOk())\n                .andExpect(jsonPath(\"$.mes\").value(\"2026-10\"));\n    }\n}\n"};
